INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('003653a4b59c91d6ccd4cc9f7b1c863e','德穆楚克栋鲁普','希贤',null,'1902','1966','exact','exact','内蒙古锡林郭勒盟苏尼特右旗','["\\u5FB7\\u738B"]','["\\u4F2A\\u8499\\u7586\\u653F\\u6743\\u9996\\u8111","\\u8499\\u53E4\\u738B\\u516C","\\u6218\\u72AF"]','民国','伪蒙疆联合自治政府','德穆楚克栋鲁普（1902—1966），字希贤，内蒙古锡林郭勒盟苏尼特右旗人，蒙古族，世袭苏尼特右旗札萨克郡王，人称德王。早年袭爵，曾任锡林郭勒盟副盟长。1930年代，他鼓吹内蒙古自治，1933年发起百灵庙自治运动，1934年任蒙古地方自治政务委员会秘书长。1936年，他与日本关东军合作，成立伪蒙古军政府，任总裁。1937年抗日战争全面爆发后，他投靠日本，参与组建伪蒙疆联合委员会，1939年任伪蒙疆联合自治政府主席，成为日本侵略者扶植的傀儡政权首脑，协助日本对蒙疆地区进行殖民统治和经济掠夺。抗战胜利后，德王逃往北平，后被国民政府逮捕，1949年获释后前往蒙古人民共和国，1950年被引渡回中国，关押于抚顺战犯管理所。1963年特赦释放，1966年病逝于呼和浩特。德王的一生从蒙古自治运动领袖蜕变为日本侵华傀儡，是近代内蒙古历史上复杂而具争议的人物。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:46:53.493599','','长春','德惠',null,null,null,null,'内蒙古锡林郭勒盟苏尼特右旗','2','伪蒙疆联合自治政府主席','0',null,null,null);
