INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('086ee3d0096e9d4508fc87292049748a','赵甲荣',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u592A\\u539F\\u5E02\\u5E02\\u957F","\\u4F2A\\u5B98\\u5458"]','抗日战争时期','汪伪政权/日伪','赵甲荣，生卒年与籍贯不详，民国时期曾任日伪太原市市长，属抗战时期华北沦陷区伪政权官员。太原于1937年11月沦陷后，日本侵略者在当地扶植伪山西省公署与伪太原市公署，赵甲荣出任伪太原市市长，充当日本占领当局推行殖民统治、征发物资与镇压抗日活动的工具。其任职期间协助日伪维持治安、推行保甲与物资统制，为日军侵华战争服务。抗战胜利后，国民政府对其汉奸身份进行追究，但具体审判与结局因史料零散而难以确证。目前关于赵甲荣的可靠记载极为有限，其生年、籍贯、任职起讫时间及战后下落均缺乏系统史料支撑，仅能依据伪政权职官名录与地方志片段确认其曾任伪太原市市长一职。','[]','2026-09-12 13:06:46.288172','2026-09-16 06:35:40.261068','','太原','示范',null,null,null,null,'','3','伪太原市市长','0',null,null,null);
