INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('0e45a74034774721a6e884c29be6283f','王永清',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u8D64\\u5CF0\\u8B66\\u5BDF\\u5C40\\u5C40\\u957F","\\u4F2A\\u6EE1\\u5B98\\u5458"]','民国','汪伪/伪满洲国','王永清，生卒年与籍贯不详，民国时期曾任伪赤峰警察局局长。赤峰地处热河，1933年日军侵占热河后划入伪满洲国版图，伪满政权在赤峰设县公署与警察机构，王永清出任伪赤峰警察局局长，成为日本侵略者控制当地治安、镇压抗日力量与民众的工具。任职期间，他统辖伪警察队伍，配合日军清乡、搜查、抓捕抗日人员与嫌疑民众，推行保甲连坐与户口清查，压制民众反抗，为日伪殖民统治服务。其具体任职起讫、罪行细节及此后去向，现存公开史料记载甚少，尚待进一步查证。','[]','2026-09-15 07:31:58.788075','2026-09-15 07:32:27.743173','',null,null,null,null,null,null,'',null,null,'0',null,null,null);
