INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('0e5def22df82df2b08a3fccd9d9d4275','邢士廉','隅三',null,'1885','1954','exact','exact','奉天省沈阳县','[]','["\\u5949\\u7CFB\\u5C06\\u9886","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u6C49\\u5978"]','民国','奉系军阀、伪满洲国','邢士廉（1885年—1954年），字隅三，辽宁沈阳人，满族。日本陆军士官学校第八期骑兵科毕业，历任东北陆军第十九混成旅参谋长、第二十四混成旅旅长、第二十师师长等职。1928年作为张学良代表参与东北易帜谈判，是张学良派赴北平与蒋介石等人商谈东北易帜问题的代表之一 [6]，同年8月抵上海探询中央对日外交机宜 [7]，后任中国国民党辽宁省党部指导委员兼常务委员、东北边防军司令长官公署顾问、东北讲武堂教育长。
