INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('12c5384cd1e5a25b60289e57f50bd79c','李寿山',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u5B98\\u5458","\\u8B66\\u52A1\\u79D1\\u957F","\\u6C49\\u5978","\\u4F2A\\u53BF\\u957F","\\u4F2A\\u6EE1\\u5B98\\u5458"]','抗日战争时期','汪伪政权/伪满洲国','李寿山，生卒年与籍贯不详，民国时期曾任伪岫岩县县长。岫岩县位于辽宁省东南部，九一八事变后随东北全境沦陷，被日本关东军扶植的伪满洲国控制。李寿山在伪满统治时期出任岫岩县伪县长，成为日本侵略者推行殖民统治、征发劳役、掠夺物资、镇压抗日民众的地方代理人。其任内执行伪满法令，配合日伪军警维持治安、搜捕抗日人员，对当地民众实施高压统治。抗战胜利后，伪满政权覆灭，李寿山的下落与最终结局缺乏可靠史料记载。因史料散佚，其具体生年、籍贯、任职起讫时间及战后处理情况均待进一步考证。','[]','2026-09-12 13:06:46.288172','2026-09-16 08:45:59.479879','','鞍山','岫岩',null,null,null,null,'','4','伪岫岩县县长','0',null,null,null);
