INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('1309a7fc63a04c622ac1ab68ae341c1b','叶恭绰','裕甫','遐庵','1881','1968','exact','exact','广东番禺','["\\u53F6\\u8A89\\u864E","\\u9050\\u7FC1"]','["\\u4EA4\\u901A\\u7CFB\\u5B98\\u5458","\\u5B66\\u8005","\\u4E66\\u753B\\u5BB6","\\u6536\\u85CF\\u5BB6"]','民国','交通系','叶恭绰，字裕甫，号遐庵，广东番禺人。清末举人，早年留学日本，加入同盟会。民国后历任交通部次长、总长，兼理交通银行，为旧交通系核心人物。曾主持铁路建设与邮电改革，推动交通事业发展。1920年代后退出政坛，致力于文化教育与书画收藏。抗战期间拒任伪职，保持民族气节。新中国成立后任中央文史研究馆副馆长、全国政协委员。精于诗词、书画、鉴藏，编有《全清词钞》《遐庵汇稿》等，1968年在北京逝世。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:58:49.776904','','','',null,null,null,null,'广东番禺','2','伪交通部长','0',null,null,null);
