INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('14116dc17426baf61c927aa474624cc4','曹汝霖','润田','觉庵','1877','1966','exact','exact','江苏上海','["\\u66F9\\u6DA6\\u7530"]','["\\u5916\\u4EA4\\u5B98","\\u653F\\u6CBB\\u5BB6","\\u5317\\u6D0B\\u653F\\u5E9C\\u5B98\\u5458","\\u65E5\\u672C\\u63D0\\u51FA\\u201C\\u4E8C\\u5341\\u4E00\\u6761\\u201D"]','民国','北洋政府交通系','曹汝霖，字润田，号觉庵，江苏上海人，1877年生于上海。早年留学日本，毕业于东京法学院。归国后历任清政府外务部副大臣、北洋政府外交次长、交通总长、财政总长等职，为交通系核心人物。1915年参与中日“二十一条”谈判，1919年五四运动中被指为卖国贼，住宅遭焚，自此退出政坛。后从事慈善与实业，曾任中国红十字会会长。抗日战争时期拒绝出任伪职，保持民族气节。1949年后移居香港，后赴美国，1966年病逝于美国。其一生功过交织，既有外交屈辱之责，亦有晚节可嘉之评。','[]','2026-09-12 13:06:46.288172','2026-09-15 07:11:03.207230','','东城；昌平；海淀；北辰；和平；河北；滨海；廊坊','微山；固安',null,null,null,null,'上海','1','伪华北政务委员会咨询委员','0',null,null,null);
