INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('1667fea003ab1b83029e52d06308cc2f','倪道烺',null,null,'1879','1952','approx','approx','安徽阜阳','["\\u502A\\u9053\\u6717","\\u502A\\u9053\\u6717","\\u502A\\u9053\\u70FA"]','["\\u4F2A\\u5B89\\u5FBD\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978","\\u4F2A\\u5B89\\u5FBD\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权','倪道烺，安徽阜阳人，民国时期皖系地方军政人物。早年投身军旅，属皖系阵营，曾任安徽陆军混成旅旅长等职。抗日战争爆发后，倪道烺投靠日本侵略者，沦为汉奸。1938年日军侵占安徽后，他出面组织伪政权，先后出任伪安徽省维新政府省长、汪伪国民政府安徽省省长等要职，协助日军推行殖民统治，搜刮民财、镇压抗日力量。抗战胜利后，倪道烺被国民政府逮捕，以汉奸罪受审，后获释或病死于狱中，具体结局史料记载不一。其一生由地方军人蜕变为民族罪人，是抗战时期安徽地区伪政权的重要代表人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 08:36:10.285123','','','',null,null,null,null,'安徽阜阳','2','汪伪安徽省省长','0',null,null,null);
