INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('1a4bf67b4299d690a663af0096489d0c','苏锡文',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u4E0A\\u6D77\\u7279\\u522B\\u5E02\\u526F\\u5E02\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','汪伪政权','苏锡文，生卒年与籍贯不详，民国时期曾任伪上海特别市副市长，属汪伪政权系统官员。1937年11月上海沦陷后，日本侵略者扶植成立伪上海市大道政府，苏锡文出任伪市长，成为日军占领上海初期的主要傀儡之一。1938年伪维新政府成立后，伪上海市政权改组，苏锡文改任伪上海特别市副市长，在伪市长傅筱庵之下继续为日伪维持统治秩序、推行殖民政策。其任职期间协助日军征发物资、镇压抗日活动、推行奴化宣传，是上海沦陷区汉奸政权的重要成员。抗战胜利后，国民政府对其汉奸罪行进行清算，其具体结局因史料零散而记载不一。苏锡文作为汪伪政权在上海的重要代理人，其活动是研究上海沦陷区殖民统治与汉奸政权运作的重要个案。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:14:10.122493','','浦东；黄浦；绍兴；厦门','',null,null,null,null,'','2','伪上海特别市副市长','0',null,null,null);
