INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('22a0dbcdc7b27e1c6f6eaf43bbc71567','张书翰',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6FDB\\u6C5F\\u53BF\\u534F\\u548C\\u4F1A\\u4F1A\\u957F","\\u4F2A\\u6EE1\\u534F\\u548C\\u4F1A\\u5B98\\u5458"]','抗日战争时期','伪满洲国','张书翰，生卒年与籍贯不详，抗日战争时期任伪满洲国濛江县（今吉林省靖宇县）协和会会长。满洲国协和会系日本关东军扶植的官办法西斯团体，标榜“王道乐土”“民族协和”，实为协助日伪推行殖民统治、镇压抗日力量、搜刮民力物资的工具。张书翰作为濛江县协和会负责人，参与推行保甲连坐、集团部落、物资统制与“思想工作”，配合日伪军警对抗联及抗日民众进行诱降、告密、宣抚与搜捕，为日本侵略者在濛江一带的殖民统治效力。濛江是东北抗日联军第一路军活动的重要区域，杨靖宇将军即于1940年在濛江县境牺牲，协和会在其中负有配合“讨伐”与切断民众支援的责任。张书翰的具体生平行迹、任职起讫及战后结局，因史料零散，尚待进一步查证。','[]','2026-09-12 13:06:46.288172','2026-09-15 07:54:40.666725','','白山；锦州；佳木斯；哈尔滨；大庆；齐齐哈尔','桦川；南岗；肇源；克东；甘南',null,null,null,null,'','2','伪濛江县协和会会长','0',null,null,null);
