INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('24906f8d6c50236c868e5a3aab544c02','罗振玉','叔蕴、叔言','雪堂、贞松老人','1866','1940','exact','exact','浙江上虞','["\\u7F57\\u53D4\\u8A00","\\u7F57\\u96EA\\u5802","\\u8D1E\\u677E\\u8001\\u4EBA"]','["\\u5B66\\u8005","\\u91D1\\u77F3\\u5B66\\u5BB6","\\u6566\\u714C\\u5B66\\u5BB6","\\u7532\\u9AA8\\u5B66\\u5BB6","\\u6E05\\u9057\\u6C11","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458"]','清末','清遗民、伪满洲国','罗振玉（1866—1940），字叔蕴、叔言，号雪堂、贞松老人，浙江上虞人，生于江苏淮安。清末著名学者，在甲骨学、敦煌学、金石学、目录学等领域有开创性贡献，与王国维并称“罗王”。他早年创办《农学报》、东文学社，后入端方幕。辛亥革命后以清遗民自居，长期旅居日本，从事学术研究。1924年入直南书房，参与清室善后事宜。九一八事变后，他积极参与策划伪满洲国，1932年任伪满洲国参议府参议、监察院院长等职，成为汉奸。晚年继续学术著述，1940年病逝于旅顺。其学术成就巨大，但政治立场反动，投敌卖国，为后世所批判。
