INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('26330fecf9534b8096c8e6de0c14fb8e','张学铭','西卿',null,'1908','1983','exact','exact','辽宁海城','["\\u5F20\\u897F\\u537F"]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u9646\\u519B\\u4E2D\\u5C06"]','民国','东北军、汪伪政权','张学铭（1908—1983），字西卿，辽宁海城人，张作霖次子，张学良二弟。早年留学日本陆军士官学校，回国后加入东北军，历任连长、营长、团长等职。1931年九一八事变后，随东北军入关，后任北平绥靖公署参议、军事委员会北平分会委员等。1936年西安事变后，东北军被分化，张学铭对蒋介石不满。抗日战争爆发后，张学铭于1940年投靠汪精卫伪政权，任汪伪军事委员会委员、伪陆军部次长、伪苏北行营主任等职，成为汪伪政权中的东北军代表之一。他参与伪军建设与“清乡”活动，协助日军维持占领区统治。抗战胜利后，张学铭被国民政府逮捕，以汉奸罪判处有期徒刑。1949年后获释，定居北京，曾任北京市政协委员等职。1983年在北京病逝。','[]','2026-09-15 06:44:11.787837','2026-09-15 06:44:31.951108','',null,null,null,null,null,null,'辽宁海城',null,null,'0',null,null,null);
