INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('26edb12c6e141c84e1b6c5fd3d21f3b1','江亢虎','亢虎','洪水','1883','1954','exact','exact','江西弋阳','["\\u6C5F\\u7ECD\\u94E8","\\u5EB7\\u74E0","\\u6C5F\\u6D2A"]','["\\u4F2A\\u653F\\u6743\\u5B98\\u5458","\\u6C49\\u5978","\\u653F\\u5BA2","\\u5B66\\u8005"]','民国','汪伪政权','江亢虎，原名绍铨，江西弋阳人。早年留学日本，接触社会主义思潮，1911年创立中国社会党，为中国最早宣传社会主义者之一。后赴美国、欧洲游历讲学，曾任加拿大皇家学院教授。抗日战争爆发后，江亢虎留居沦陷区，1939年应汪精卫之邀参加汪伪政权，历任汪伪国民政府委员、考试院院长、铨叙部部长等职，成为汪伪集团重要成员。他利用其学者身份为日伪统治张目，鼓吹“和平建国”，影响恶劣。抗战胜利后，江亢虎以汉奸罪被国民政府逮捕，判处无期徒刑。1954年病死于上海提篮桥监狱。其一生由早期社会主义宣传者蜕变为汉奸，为后世所诟病。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:41:28.799152','','昆明；宣城；普洱；桂林；南京；泰州；上饶；九江；合川；西安','呈贡；旌德；绩溪；西；永福；六合；江宁；浦口；雨花台；泰州医药高；婺源；弋阳；浔阳',null,null,null,null,'江西弋阳','2','伪国民政府考试院院长','0',null,null,null);
