INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('27b7671218a5426ee8840a7978972c82','陈清保',null,null,null,null,'exact','exact','福建厦门同安','[]','["伪同安区保甲长"]','抗日战争时期','','伪职：伪同安区保甲长','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','福建','厦门','同安',null,null,null,null,'','6','伪同安区保甲长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('27c81127a5e1ddc0e7562af98db0a14f','王缵绪','治易','治园','1885','1960','exact','exact','四川西充','["\\u738B\\u74D2\\u7EEA","\\u738B\\u6CBB\\u6613","\\u6CBB\\u56ED\\u8001\\u4EBA"]','["\\u5DDD\\u519B\\u5C06\\u9886","\\u56DB\\u5DDD\\u7701\\u4E3B\\u5E2D","\\u8D77\\u4E49\\u5C06\\u9886"]','民国','川军','王缵绪，字治易，号治园，四川西充人。早年入四川陆军速成学堂，后加入同盟会。历任川军排长、连长、营长、团长、旅长、师长、军长等职，为川军重要将领。1920年代至1930年代，参与四川军阀混战，先后依附杨森、刘湘等。1938年任四川省政府主席，同年兼任第二十九集团军总司令，率部出川参加抗日战争，转战鄂西、湘北等地。1940年辞去省主席职，专任军事。抗战胜利后，任武汉行营副主任、重庆卫戍总司令等职。1949年12月在四川率部起义，投向中国人民解放军。中华人民共和国成立后，曾任西南军政委员会委员、四川省人民政府参事室主任等职。1960年在成都病逝。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:46:22.831342','','南充','',null,null,null,null,'四川西充','2','省级长官','0',null,null,null);
