INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('29235044ec6fd13ccb32b39028ed497b','吕荣寰',null,null,'1890','1951','approx','approx','辽宁抚顺','[]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u4E2D\\u4E1C\\u94C1\\u8DEF\\u7763\\u529E","\\u6C49\\u5978"]','民国','奉系、伪满洲国','吕荣寰，辽宁抚顺人，奉系官僚。早年入奉系阵营，历任奉天省议会议员、中东铁路督办等职。1929年中东路事件中，吕荣寰在张学良支持下强行接收中东铁路，驱逐苏方人员，引发中苏武装冲突，东北军战败后被迫恢复原状。九一八事变后，吕荣寰投敌附逆，出任伪满洲国要职，历任伪满哈尔滨市市长、伪满驻南京大使、伪满外交部大臣等，成为日本侵略者推行殖民统治的得力工具。抗战胜利后，吕荣寰被苏联红军逮捕，押往苏联，1951年前后死于苏联狱中。其一生由奉系官员堕落为汉奸，是民国时期东北政坛投敌卖国的典型人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:06:08.550632','','延边；经开区；聊城；哈尔滨；抚顺','延吉；茌平',null,null,null,null,'辽宁抚顺','2','伪满洲国产业部大臣、伪民生部大臣','0',null,null,null);
