INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('296d9ef8411666e20edc959839e85e9c','温宗尧','钦甫',null,'1876','1947','approx','exact','广东台山','["\\u6E29\\u94A6\\u752B"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u7ACB\\u6CD5\\u9662\\u957F","\\u6C49\\u5978"]','民国','汪伪政权','温宗尧，字钦甫，广东台山人，清末民初政治人物。早年留学美国，归国后入两广总督岑春煊幕，历任广东洋务局总办、外务部参议等职。民国成立后，曾任驻沪通商交涉使、广东军政府外交部长、南方军政府总裁等职，为政学系要角。抗日战争爆发后，温宗尧于1938年公开投敌，参与筹组伪中华民国维新政府，任伪立法院长。1940年汪伪国民政府成立后，继续担任伪立法院长、伪司法院长等要职，为汪伪政权核心人物之一，积极推行日本侵略政策，出卖国家主权。抗战胜利后，温宗尧于1945年被国民政府逮捕，1947年以汉奸罪判处无期徒刑，同年病死于南京狱中。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:40:24.699516','','南京；江门','栖霞',null,null,null,null,'广东台山','2','伪维新政府立法院长','0',null,null,null);
