INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('2f4675713681e9ef60795ab663edbd0b','李福和',null,null,'1892','1938','approx','exact','热河省','["\\u674E\\u798F\\u548C"]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u4F2A\\u519B\\u5934\\u76EE","\\u6C49\\u5978"]','抗日战争时期','东北军、伪军','李福和，热河人，早年投身军旅，隶东北军系统，累升至骑兵师师长，授少将衔。1931年九一八事变后随东北军入关。1937年七七事变后，华北沦陷，李福和于1937年冬率部投降日军，被编为伪“皇协军”第一军，任军长，驻防河南安阳、林县一带，配合日军“扫荡”抗日根据地，残害百姓。1938年8月，其部属在河南林县发动起义，李福和及日军顾问数十人被击毙。李福和是抗战初期较早投敌的东北军高级将领之一，其叛国行为严重削弱了华北抗日力量，后被其部下反正时所杀，成为汉奸可耻下场的典型。','[]','2026-09-12 13:06:46.288172','2026-09-15 06:50:47.808731','','菏泽；衡水；邯郸；南阳；安阳；许昌','菏泽经开区；安平；武邑；临漳；复兴；成安；武安；涉县；邯郸冀南；新野；滑县；建安',null,null,null,null,'热河省','2','伪满洲国热河省军管区司令、伪满军热河警备司令','0',null,null,null);
