INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('2f5df80a696995f6b503b58f926b4bfc','金永昌',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u53C2\\u4E8B\\u5B98"]','民国','伪满洲国','金永昌，生卒年及籍贯不详，民国时期曾任伪满洲国兴安北省参事官。兴安北省为伪满洲国1932年设立于内蒙古东部呼伦贝尔地区的省份，省公署初驻海拉尔，后迁满洲里。参事官为省公署高级职务，多由日本人或亲日蒙古族、汉族人士充任，负责辅佐省长处理行政事务，实权常操于日籍参事官之手。金永昌出任此职，表明其属于伪满洲国政权体系中的地方官员，参与日本关东军控制下的殖民统治。关于其具体任期、施政活动及个人背景，目前公开史料记载极为有限，尚待进一步发掘档案文献予以考证。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:25:05.897992','','呼伦贝尔；赤峰；锡林郭勒；张家口','满洲里；牙克石；喀喇沁旗；松山；正蓝旗；尚义',null,null,null,null,'','2','伪满洲国兴安北省参事官','0',null,null,null);
