INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('31604d06aba54aa48a69447f9486f394','潘国屏',null,null,null,null,'unknown','unknown','','[]','["\\u4E1C\\u5317\\u519B\\u519B\\u5B98","\\u5C11\\u5C06\\u526F\\u5E08\\u957F","\\u653F\\u8BAD\\u5904\\u5904\\u957F","\\u88AB\\u4FD8\\u6295\\u654C\\u8005"]','民国','东北军；后投敌附逆','潘国屏，生平籍贯与生卒年不详，民国时期东北军军官，曾任东北军第113师少将副师长兼政训处处长。1930年代前期，东北军第113师隶属第51军系统，驻防华中、西北一带。1936年西安事变前后，东北军内部动荡，第113师师长李振唐等部在事变后接受南京政府整编。抗日战争全面爆发后，东北军各部被调往各战场参战，潘国屏所在部队亦卷入对日作战。据相关史料记载，潘国屏在作战中被日军俘虏，随后变节投敌，出任伪职，为日军及伪政权效力，具体投敌经过、所任伪职及此后行踪，现存公开史料记载零散，难以确证。其由东北军将领沦为附逆人员，是抗战时期部分被俘军官丧失民族气节的典型案例，具体罪行细节尚待进一步档案发掘。','[]','2026-09-15 06:53:31.971149','2026-09-15 06:53:46.100324','',null,null,null,null,null,null,'',null,null,'0',null,null,null);
