INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('32bcb5a336904f889b861be13bdd8ca0','吴松林',null,null,null,null,'unknown','unknown','','[]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u519B\\u5B98","\\u4F2A\\u6EE1\\u519B\\u653F\\u4EBA\\u5458"]','民国','东北军系统；后投伪满洲国','吴松林为民国时期东北军系统军官，曾任龙江省防骑兵第一旅少将旅长。九一八事变后，日军侵占东北，马占山一度在江桥抗战中率部抵抗，吴松林所部亦属龙江省防军序列。1932年前后，在日军军事压力与政治诱降下，吴松林随部分东北军将领投附日本，所部被编入伪满洲国军警系统，成为日本关东军控制东北的地方武装之一。其投日后具体任职、部队番号变迁及晚年结局，公开史料记载零散，尚难确证。作为由东北军将领转为伪满军政人员的人物，其经历反映了九一八后东北地方军政势力在抵抗、动摇与投降之间的分化，具有典型的时代悲剧色彩，亦留下附敌失节的历史污点。','[]','2026-09-15 06:23:17.440787','2026-09-15 06:23:38.053658','',null,null,null,null,null,null,'',null,null,'0',null,null,null);
