INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('3b455e11095cffed7adb7b2ebac3f914','傅式说',null,null,'1891','1947','approx','exact','浙江乐清','["\\u5085\\u7B51\\u9690","\\u5085\\u5F0F\\u8BF4\\uFF08\\u5B57\\uFF09"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u6D59\\u6C5F\\u7701\\u957F","\\u6C49\\u5978","\\u6559\\u80B2\\u5BB6"]','民国','汪伪政权','傅式说，字筑隐，浙江乐清人，早年留学日本，毕业于东京帝国大学，回国后从事教育与实业，曾任上海大夏大学教授、国民政府交通部次长等职。抗日战争爆发后，傅式说于1938年追随汪精卫投敌，参与汪伪政权筹建，历任汪伪国民党中央委员、伪行政院政务委员、伪浙江省政府主席等要职，成为汪伪政权在浙江的最高行政长官，推行奴化教育、配合日军“清乡”与经济掠夺，为虎作伥。抗战胜利后被国民政府以汉奸罪逮捕，1947年在南京老虎桥监狱被处决。其一生由学者、官员沦为民族罪人，是汪伪政权中级别较高的汉奸之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:33:43.999632','','温州；丽水；台州','乐清；青田；淳安；椒江；瑞安',null,null,null,null,'浙江乐清','2','伪浙江省长','0',null,null,null);
