INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('3b8cb3c2f6068bf6d1a6cc017e843572','陶德坤',null,null,null,null,'exact','exact','乍浦','[]','["伪平湖乍浦商会会长"]','抗日战争时期','','伪职：伪平湖乍浦商会会长；罪行：商界汉奸，为日军筹措物资，胁迫商户出钱出物资敌，盘剥沿海商贸。；结局：抗日武装攻克乍浦，当场捕获枪决。','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','浙江','嘉兴','',null,null,null,null,'','5','伪平湖乍浦商会会长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('3b92883ce32b0c290b1862dbf3934106','邓祖禹',null,null,null,null,'unknown','unknown','','[]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u6C5F\\u897F\\u7701\\u653F\\u5E9C\\u59D4\\u5458"]','民国','汪伪政权','邓祖禹，生卒年与籍贯不详，民国时期曾任汪伪政权江西省政府的委员。抗日战争进入相持阶段后，汪精卫于1940年在南京成立伪国民政府，为粉饰其傀儡统治，在日军占领或势力所及的省份拼凑伪省政府，网罗地方士绅与失意政客充任委员。邓祖禹即在这样的背景下出任伪江西省政府委员，成为汪伪政权在江西地区的组成部分。伪江西省政府名义上管辖江西沦陷区事务，实则秉承日军旨意，推行所谓“和平反共建国”，协助日军征发物资、维持治安、推行奴化宣传，对江西民众造成压迫与损害。邓祖禹作为该伪政权委员，参与其决策与施政，属附敌为虎作伥之列。抗战胜利后，国民政府对其人如何处理，因史料散佚，详情待考。其生平事迹在现存民国人物辞典与地方志中记载极少，仅以伪职身份见于汪伪政权职官名录。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:32:11.325515','','普洱；上饶；九江；南昌；吉安；宜春；赣州','西；余干；婺源；新建；东湖；安义；青山湖；永新；高安；于都；信丰；全南；宁都',null,null,null,null,'','2','伪江西省政府委员、伪南昌市长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('3b940f12368d66cc856b132fafec171c','达瓦敖斯尔',null,null,null,null,'unknown','unknown','内蒙古扎赉特旗（今属兴安盟）','[]','["\\u4F2A\\u624E\\u8D49\\u7279\\u65D7\\u8B66\\u52A1\\u79D1\\u957F","\\u4F2A\\u6EE1\\u5B98\\u5458"]','民国','伪满洲国/蒙古地方势力','达瓦敖斯尔，生卒年不详，内蒙古扎赉特旗（今属兴安盟）蒙古族人。九一八事变后，日本关东军侵占东蒙地区，扶植伪满洲国，并在各旗县设立警察、警务机构以强化殖民统治。达瓦敖斯尔于伪满时期出任伪扎赉特旗警务科长，执掌该旗警察事务，负责维持地方治安、编练警察队、配合日伪军警镇压抗日活动与搜捕抗日人员，是日本侵略者推行“以蒙治蒙”政策的基层执行者之一。其具体任职起讫、籍贯家世及战后去向，因史料零散、档案多存于地方志与日伪档案中，尚待进一步查证。作为伪满基层警务官员，其行为属于投敌附逆、为虎作伥性质，是日本殖民统治东蒙地区的工具之一。','[]','2026-09-12 13:06:46.288172','2026-09-15 09:09:35.727895','','兴安','扎赉特旗；科尔沁右翼前旗',null,null,null,null,'','2','伪扎赉特旗警务科长','0',null,null,null);
