INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('3d82f625f5c28dd1020768f87b807898','文画君',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u8499\\u7586\\u653F\\u5E9C\\u5B98\\u5458","\\u53F8\\u6CD5\\u90E8\\u957F"]','抗日战争时期','伪蒙疆联合自治政府','文画君，生卒年及籍贯不详，是抗日战争时期伪蒙疆联合自治政府中的司法官员。1937年日军占领张家口后，扶植德穆楚克栋鲁普等蒙古王公成立伪蒙疆联合委员会，后改组为伪蒙疆联合自治政府。文画君在该伪政权中出任司法部长，负责推行日伪法律与殖民统治秩序，协助日军镇压抗日活动、管控民众。其具体任职时间、施政细节及个人生平因史料匮乏而难以详考。作为伪政权高级官员，其行为属于投敌附逆，战后可能受到相应惩处，但缺乏明确记载。本条目仅依据伪蒙疆政府组织名录等有限资料整理，待新史料发现后补充。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:14:41.626543','','','',null,null,null,null,'','2','伪蒙疆政府司法部长','0',null,null,null);
