INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('3f2de29995a6065290d2d8b0f8b717c8','王缵绪','治易',null,'1885','1960','exact','exact','四川省西充县','["\\u738B\\u6CBB\\u6613","\\u738B\\u74D2\\u7EEA"]','["\\u5DDD\\u519B\\u5C06\\u9886","\\u56DB\\u5DDD\\u7701\\u4E3B\\u5E2D","\\u6297\\u65E5\\u5C06\\u9886","\\u8D77\\u4E49\\u5C06\\u9886"]','民国','川军','王缵绪，字治易，四川西充人，清末秀才出身，后入四川陆军速成学堂，为刘湘部重要将领。历任川军师长、军长，1938年刘湘病逝后一度代理四川省政府主席，旋由蒋介石自兼，王改任省府委员。抗战期间率部出川，任第二十九集团军总司令，参加武汉会战、随枣会战等，后任第六战区副司令长官。1940年代曾任重庆市市长、四川省参议会议长。1949年12月在成都率部起义，投向中共。中华人民共和国成立后，曾任西南军政委员会委员、四川省人民政府参事室主任等职，1960年在成都病逝。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:46:31.275439','','南充；成都；万州；合川；大足；沙坪坝','双流；邛崃；金堂',null,null,null,null,'四川省西充县','2','川军将领、四川省政府主席','0',null,null,null);
