INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('40a350ab1d6b29c54e8457a9d85f1c61','叶蓬','孛孛','一忠','1897','1946','approx','exact','湖北黄陂','["\\u53F6\\u5B5B\\u5B5B","\\u53F6\\u4E00\\u5FE0"]','["\\u4F2A\\u6B66\\u6C49\\u7EE5\\u9756\\u516C\\u7F72\\u4E3B\\u4EFB","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权','叶蓬，字孛孛，号一忠，湖北黄陂人，生于1897年前后。早年入保定陆军军官学校第六期，毕业后在鄂军服役，历任排长、连长、营长等职。1926年北伐后，叶蓬投靠蒋介石，任武汉警备司令部参谋长、警备旅旅长等职。1930年代因贪污及与日本方面勾结被撤职。抗日战争爆发后，叶蓬于1938年武汉沦陷后投敌，加入汪精卫伪政权，历任伪武汉绥靖公署主任、伪湖北省政府主席、伪军事委员会委员等要职，积极协助日军维持占领区治安、搜刮物资、镇压抗日力量。1945年抗战胜利后，叶蓬被国民政府逮捕，以汉奸罪判处死刑，1946年在武汉执行枪决。叶蓬为民国时期典型投敌叛国者，其一生由地方军阀转变为汪伪政权要员，最终受到历史审判。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:58:35.785230','','武汉；芜湖；唐山；十堰；孝感；株洲；高；湘潭；湘西；衡阳；郴州','黄陂；镜湖；路南；房县；孝南；渌口；醴陵；湘乡；泸溪；雁峰',null,null,null,null,'湖北黄陂','2','伪陆军部长','0',null,null,null);
