INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('426214cec7daa4e19b180c48aad29b85','顾忠琛',null,null,'1874','1945','approx','approx','江苏无锡','["\\u987E\\u5FE0\\u6DF1"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u6C5F\\u82CF\\u7701\\u957F","\\u6C49\\u5978"]','民国','国民党（后投汪伪）','顾忠琛，江苏无锡人，清末投身军界，早年加入同盟会，参与辛亥革命，曾任江浙联军总参谋、南京临时政府参谋次长等职。民国时期长期在军政界任职，曾任江苏省政府委员、国民政府参军处参军等。抗日战争爆发后，顾忠琛滞留沦陷区，1938年投靠日本侵略者，参加汪精卫伪政权，历任汪伪国民政府委员、伪江苏省政府主席兼民政厅长等要职，成为汪伪政权在江苏地区推行殖民统治的重要人物。他协助日军征粮、清乡，镇压抗日力量，危害甚大。抗战胜利前夕，顾忠琛于1945年病死于苏州，未及受到审判。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:13:13.843045','','南京；无锡','建邺',null,null,null,null,'江苏无锡','2','伪安徽省保安司令','0',null,null,null);
