INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('446f6e23388edb67a15f15dd1f074e89','梅思平','祖芬',null,'1896','1946','approx','exact','浙江永嘉','["\\u6885\\u7956\\u82AC"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978","\\u4F2A\\u5DE5\\u5546\\u90E8\\u957F","\\u4F2A\\u5185\\u653F\\u90E8\\u957F"]','民国','汪伪政权','梅思平，字祖芬，浙江永嘉人，生于1896年前后。早年就读于北京大学政治系，曾参加五四运动。后任中央政治学校教授、江宁实验县县长等职。1938年抗战期间，他受汪精卫指派，与高宗武等秘密赴上海与日方代表影佐祯昭、今井武夫等谈判，参与策划汪精卫叛国投敌，并签订卖国密约。1939年随汪精卫赴南京，参与建立汪伪政权。1940年汪伪国民政府成立后，历任伪工商部部长、伪内政部部长、伪浙江省政府主席等要职，积极推行日军侵略政策，搜刮物资，镇压抗日活动。1945年抗战胜利后被捕，1946年以汉奸罪被判处死刑，在南京执行枪决。','[]','2026-09-12 13:06:46.288172','2026-09-16 13:02:49.945684','','温州；宣城；金华','永嘉；瑞安',null,null,null,null,'浙江永嘉','1','伪奉贤县教育督办','0',null,null,null);
