INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('451206b359a341847672452323422d87','赵仲仁',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u5B98\\u5458","\\u7EF4\\u6301\\u4F1A\\u4F1A\\u957F"]','民国','伪满洲国','赵仲仁，生卒年及籍贯不详，民国时期活动于今吉林省白城子（今白城市）一带。九一八事变后，日军侵占东北，赵仲仁投靠日本侵略势力，出任伪满白城子地区维持会会长，充当日伪政权在地方推行殖民统治、维持治安与搜刮物资的工具。维持会系日军在占领初期扶植的临时性汉奸组织，负责为日军筹粮派款、登记户口、协助“宣抚”与镇压抗日力量。赵仲仁作为该会负责人，参与维持地方“秩序”、配合日军统治，其具体罪行因史料散佚而难以详考，仅见于地方志及伪满档案的零星记载。抗战胜利后，其下落不明。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:20:51.141751','','白城；朝阳；哈尔滨；大兴安岭；大庆；齐齐哈尔；绥化；鹤岗','洮北；北票；建平；巴彦；道外；道里；呼玛；红岗；让胡路；兰西；海伦；绥棱；工农；泰来；甘南',null,null,null,null,'','2','伪满白城子地区维持会会长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('4514cd951a0c4161a79fb7bf18556ffa','曹秉深',null,null,null,null,'unknown','unknown','','[]','["\\u4E1C\\u5317\\u6D77\\u519B\\u5C06\\u9886","\\u4F2A\\u6EE1\\u6C5F\\u4E0A\\u519B\\u4E2D\\u5C06\\u53F8\\u4EE4","\\u4F2A\\u6EE1\\u5B98\\u5458"]','民国','东北海军、伪满洲国','曹秉深原为东北海军军官，曾任少将。1931年九一八事变后，东北海军部分舰艇被日军俘获，曹秉深选择投靠日本，参与伪满洲国江防舰队的组建。1932年伪满洲国成立后，江防舰队改编为江上军，曹秉深出任江上军中将司令，成为伪满军事体系中的重要人物。他指挥的江上军主要负责松花江、黑龙江等水域的巡逻与警备，配合日军维持殖民统治，镇压抗日武装。其具体生卒年、籍贯及早年经历因史料匮乏而难以确证，但作为伪满高级将领，其投敌行为在抗战胜利后受到历史审判。','[]','2026-09-15 06:34:33.529497','2026-09-15 06:34:52.833264','',null,null,null,null,null,null,'',null,null,'0',null,null,null);
