INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('4a70a95d2524d40f68a1d2fbf6318e66','张维玺',null,null,'1889','1944','approx','approx','河北馆陶','[]','["\\u897F\\u5317\\u519B\\u5C06\\u9886","\\u4F2A\\u653F\\u6743\\u5B98\\u5458"]','民国','西北军（冯玉祥系）','张维玺，河北馆陶人，西北军将领，冯玉祥旧部。早年投身北洋军，后隶冯玉祥国民军系统，历任团长、旅长、师长等职，为西北军“五虎将”之一，以作战勇猛著称。1926年随冯玉祥参加五原誓师，后参与北伐。1930年中原大战时率部属冯玉祥一方，任前敌总指挥等职，战败后西北军瓦解，张维玺去职闲居。抗日战争爆发后，张维玺滞留华北，后投靠日伪，出任汪伪政权军事参议院参议、伪河北省政府官员等职，为日军维持华北占领区秩序效力。1944年前后病故。其由抗日阵营转入附敌，晚节不保，为时人所讥。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:24:02.788079','','桂林','灵川',null,null,null,null,'河北馆陶','2','伪和平建国军第三方面军副总司令','0',null,null,null);
