INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('4c7f34e94536ad217f8890d40a7c47d1','赵承绶','印甫',null,'1891','1966','exact','exact','山西五台','["\\u8D75\\u5370\\u752B"]','["\\u664B\\u7EE5\\u519B\\u5C06\\u9886","\\u56FD\\u6C11\\u9769\\u547D\\u519B\\u4E2D\\u5C06","\\u8D77\\u4E49\\u5C06\\u9886"]','民国','晋绥军（阎锡山部）','赵承绶，字印甫，山西五台人，晋绥军重要将领。早年入保定陆军军官学校第五期，毕业后投效阎锡山，历任晋绥军排、连、营、团、旅长等职，参与中原大战等役。抗日战争爆发后，任骑兵第一军军长、第七集团军总司令等职，率部参加绥远抗战、太原会战等，在晋北、绥远一带与日军作战。抗战后期任山西省政府委员、第二战区副司令长官等。1946年任太原绥靖公署副主任兼野战军总司令，参加上党战役、汾孝战役等。1948年晋中战役中，所部被人民解放军包围，赵承绶于7月16日在太谷小常村被俘。被俘后经教育改造，思想转变，1949年后曾任山西省人民政府委员、山西省政协副主席等职，1966年在太原病逝。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:03:04.545583','','乌兰察布；包头；呼和浩特；临汾；吕梁；大同；太原；忻州；晋中；长治；张家口；西安','丰镇；兴和；商都；东河；包头稀土高；固阳；昆都仑；石拐；呼和浩特经开区；土默特左旗；清水河；乡宁；侯马；尧都；交口；孝义；汾阳；云州；大同经开区；平城；新荣；阳曲；五台；五台山风景区；原平；平遥；祁…',null,null,null,null,'山西省五台县槐荫村','2','伪晋北自治政府参议','0',null,null,null);
