INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('4deb78da641f1b7822ce3e89859669b3','赵毓松',null,null,'1893',null,'approx','unknown','江苏','[]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u53BF\\u957F","\\u6C49\\u5978"]','民国','汪伪政权','赵毓松，江苏人，早年经历不详。抗日战争时期投靠日本侵略者，参加汪精卫伪政权，成为汪伪集团的地方官员。1938年汪精卫公开叛国投敌后，赵毓松追随其左右，在伪政权中担任伪职。据史料记载，他曾出任汪伪政权辖下的伪县长，负责为日军征发物资、维持地方治安，协助日伪推行殖民统治。在任期间，赵毓松积极配合日军“清乡”与“扫荡”，搜捕抗日志士，摊派捐税，奴化民众，对当地抗日力量造成危害。抗战胜利后，国民政府对其汉奸行为进行清算，赵毓松的下落及最终结局史料记载不详。其生平事迹散见于汪伪政权档案与地方文史资料，是研究汪伪基层政权与汉奸群体的一份个案。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:02:22.753348','','宿州；黔东南；南阳','灵璧；黎平；新野',null,null,null,null,'','2','伪安徽省民政厅厅长','0',null,null,null);
