INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5076258bef4c56e7d78e87bdfa9523a5','陈群','人鹤',null,'1890','1945','approx','exact','福建福州','["\\u9648\\u4EBA\\u9E64"]','["\\u4F2A\\u53BF\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权','陈群，字人鹤，福建福州人，早年留学日本，加入同盟会。民国时期历任国民党党政职务，1938年追随汪精卫投敌叛国，出任汪伪政权要职，先后担任伪江苏省政府主席、伪考试院院长、伪内政部部长等职，积极推行日军侵略政策，搜刮民脂民膏，镇压抗日活动。1945年抗战胜利后被捕，畏罪自杀。其一生由革命者蜕变为汉奸，为虎作伥，罪行累累，被历史唾弃。
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('507d23a37b85ac5b172823f301f65bdf','熙洽','格民',null,'1884','1952','approx','exact','辽宁沈阳','["\\u7231\\u65B0\\u89C9\\u7F57\\u00B7\\u7199\\u6D3D"]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u6E05\\u671D\\u5B97\\u5BA4","\\u6C49\\u5978"]','民国','奉系、伪满洲国','熙洽，爱新觉罗氏，字格民，辽宁沈阳人，清朝宗室。早年留学日本陆军士官学校，归国后入奉系，历任东北讲武堂教育长、吉林督军署参谋长、吉林省边防军参谋长等职。九一八事变后，熙洽于1931年9月21日打开吉林城门迎接日军，并组织伪吉林省临时政府，自任长官，宣布脱离南京国民政府。1932年伪满洲国成立后，熙洽出任财政部总长兼吉林省长，后改任宫内府大臣，成为溥仪身边的重要人物。他积极推行日本殖民政策，为伪满政权效力。1945年日本投降后，熙洽被苏联红军逮捕，后引渡回中国，关押于抚顺战犯管理所。1952年病死于抚顺战犯管理所。熙洽作为清朝宗室，在民族危亡之际投靠日本侵略者，是近代史上著名的汉奸之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 04:25:34.948360','','四平；白城；聊城；承德；秦皇岛；丹东；朝阳；沈阳；营口；葫芦岛；辽阳；锦州；阜新；鞍山；伊春；双鸭山；牡丹江；绥化；鸡西；鹤岗','伊通；双辽；洮北；白城经开区；茌平；平泉；山海关；凤城；双塔；于洪；苏家屯；大石桥；南票；绥中；灯塔；古塔；太平；彰武；千山；岫岩；铁西；大箐山；集贤；牡丹江经开区；绥芬河；肇东；城子河；兴安',null,null,null,null,'辽宁沈阳','1','伪满洲国财政部总长、伪吉林省长','0',null,null,null);
