INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('50ac023c2a81df40a7bebab137c9ed5b','钟毓',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u4F2A\\u7701\\u957F"]','民国','伪满洲国','钟毓，生卒年与籍贯不详，民国时期曾任地方行政官员。九一八事变后东北沦陷，钟毓投附日本扶植的伪满洲国政权，成为伪满官僚体系中的一员。据伪满官方职官资料，其曾出任伪黑河省省长，为该省最高行政长官，负责推行日伪当局的殖民统治政策，包括治安肃正、物资统制、劳工征发与配合日军对苏边境军事部署等事务。黑河地处中苏边境，战略地位重要，伪省长一职实为日本关东军控制北满边境、镇压抗日力量的重要工具。钟毓在任期间的施政直接服务于日本侵略利益，对当地民众造成压迫与损害。抗战胜利、伪满覆灭后，其下落及是否受到审判，因史料零散，尚待进一步考证。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:34:49.464439','','','',null,null,null,null,'','2','伪满洲国黑河省省长、伪龙江省省长','0',null,null,null);
