INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('522f41cf20fa64761cb0a77af6d79015','丁超','洁忱',null,'1884','1954','exact','exact','奉天新宾人','[]','["\\u4F2A\\u6EE1\\u5409\\u6797\\u9646\\u519B\\u4E2D\\u5C06","\\u4F2A\\u6EE1\\u519B\\u4E8B\\u54A8\\u8BAE\\u5B98","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5409\\u6797\\u5730\\u533A\\u8B66\\u5907\\u519B\\u53F8\\u4EE4\\uFF08\\u540E\\u6295\\u654C\\uFF09","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u70ED\\u6CB3\\u7701\\u8B66\\u52A1\\u5385\\u957F","\\u4F2A\\u6EE1\\u70ED\\u6CB3\\u7701\\u8B66\\u52A1\\u5385\\u957F","\\u4F2A\\u5B89\\u4E1C\\u7701\\u7701\\u957F\\uFF08\\u534E\\u4EBA\\uFF09"]','抗日战争时期','汪伪政权','丁超（1884年—1954年），字洁忱。奉天新宾人（今辽宁省新宾县邓家堡人）。1911年毕业于日本陆军士官学校步兵科。先后任东三省军械厂一等科员、吉林督署副官长、奉天军械厂材料科科长、奉天军械厂厂长、奉军总司令部兵站处处长等职。1931年辽吉事变，兼代护路军总司令。和李杜等一度组织所部反抗日本侵略军，并参加哈尔滨保卫战等重大战役，后降日。
