INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('52e5a3c16caa6dfb1169ee6f51092a44','张群','岳军',null,'1889','1990','exact','exact','四川华阳','["\\u5F20\\u5CB3\\u519B"]','["\\u56FD\\u6C11\\u515A\\u5143\\u8001","\\u5916\\u4EA4\\u5B98","\\u884C\\u653F\\u9662\\u957F","\\u603B\\u7EDF\\u5E9C\\u79D8\\u4E66\\u957F"]','民国','中国国民党','张群，字岳军，四川华阳人，国民党元老。早年留学日本陆军士官学校，加入同盟会。辛亥革命后参加二次革命、护国战争。1927年后历任国民政府军政部次长、上海市长、湖北省政府主席、外交部长等职。抗战期间任军事委员会秘书长、行政院副院长，参与对日外交。1947年任行政院长，1949年任西南军政长官公署长官，后赴台湾，历任总统府秘书长、资政等职。1990年在台北病逝。张群长期追随蒋介石，是国民党内重要政治人物，其生平跨越清末、民国至台湾时期。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:23:53.944173','','成都；资阳','彭州；金堂',null,null,null,null,'四川华阳','2','伪四川省政府主席','0',null,null,null);
