INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5566c5cae4a09258d465ea93cfc05a34','甘珠尔扎布',null,null,'1903','1970','approx','approx','内蒙古哲里木盟科尔沁左翼前旗','["\\u7518\\u73E0\\u5C14\\u624E\\u5E03"]','["\\u8499\\u53E4\\u738B\\u516C","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u4F2A\\u5174\\u5B89\\u519B\\u5C06\\u9886","\\u6218\\u72AF"]','民国','蒙古自治运动、伪满洲国、汪伪政权','甘珠尔扎布，蒙古族，内蒙古哲里木盟科尔沁左翼前旗人，出身蒙古贵族家庭。早年赴日本留学，入日本陆军士官学校，接受军事教育。归国后投身蒙古自治运动，后投靠日本关东军，参与策划蒙疆地区的所谓“自治”。伪满洲国成立后，历任伪兴安南分省省长、伪兴安军管区司令官等职，统领伪兴安军配合日军镇压抗日武装，推行殖民统治。抗日战争期间，他积极为日本侵略者效力，参与对热河、察哈尔等地的军事行动，是伪蒙疆政权的重要军事人物。抗战胜利后，甘珠尔扎布被苏联红军逮捕，后引渡回中国，关押于战犯管理所。1960年代获特赦，晚年生活于内蒙古。其一生从蒙古民族主义者蜕变为日本侵华帮凶，是近代蒙古地区投敌卖国的典型人物之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:53:41.729653','','兴安；呼伦贝尔；赤峰；通辽；锡林郭勒；白城；阜新','突泉；阿尔山；扎兰屯；扎赉诺尔；新巴尔虎右旗；新巴尔虎左旗；牙克石；鄂伦春自治旗；阿荣旗；喀喇沁旗；巴林右旗；巴林左旗；阿鲁科尔沁旗；霍林郭勒；奈曼旗；开鲁；扎鲁特旗；科尔沁左翼中旗；正镶白旗；锡林…',null,null,null,null,'内蒙古哲里木盟科尔沁左翼前旗','2','伪满洲国兴安南分省省长、伪兴安局总裁','0',null,null,null);
