INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5b0acada6a76a49a8d85ad227870f992','肖瑞臣',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6CB3\\u5357\\u7701\\u81EA\\u6CBB\\u653F\\u5E9C\\u4E3B\\u5E2D","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','汪伪政权','肖瑞臣，生卒年及籍贯不详，民国时期曾任伪河南省自治政府主席。1937年七七事变后，日军大举侵华，华北迅速沦陷。1938年前后，日军在河南占领区扶植成立伪河南省自治政府，肖瑞臣出任主席，成为日军推行殖民统治的傀儡工具。该伪政权在日军操纵下，协助维持占领区治安、征发物资、推行奴化教育，并配合日军对抗日根据地进行经济封锁与军事扫荡，严重损害了河南民众的利益与抗战事业。肖瑞臣的具体任职时间、政治活动及战后结局因史料匮乏而难以详考，其生平事迹散见于抗战时期报刊及地方档案，但缺乏系统记载。作为投敌附逆的伪政权头目，其行为属于背叛民族、为虎作伥，历来为世人所唾弃。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:38:49.060540','','','',null,null,null,null,'','2','伪河南省自治政府主席→伪河南省公署省长','0',null,null,null);
