INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5c0b19057c422e74c3cee987fce93bef','刘德权',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u5BA3\\u629A\\u73ED\\u73ED\\u957F","\\u6C49\\u5978"]','抗日战争时期','伪满洲国','刘德权，生卒年及籍贯不详，伪满洲国鞍山地区“宣抚班”班长。宣抚班是日本关东军与伪满政权在东北占领区设立的宣传与思想控制机构，名义上负责“宣抚民众”，实则配合日军进行殖民宣传、刺探情报、搜捕抗日人员、推行奴化教育。刘德权身为宣抚班班长，属伪满基层汉奸头目，其具体活动散见于地方档案与抗战史料，但缺乏系统传记资料，生平细节难以确考。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:24:36.210932','','鞍山','岫岩',null,null,'3325a2b4c950b27ad3c77cec78020058','2026-09-16 08:45:45','','7','伪满鞍山地区“宣抚班”班长','0',null,null,null);
