INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5d2a30b61a01c1d580f7f16f259f1c45','赵全德',null,null,null,null,'exact','exact','山西忻州偏关','[]','["伪偏关县警察所所长"]','抗日战争时期','','伪职：伪偏关县警察所所长；亲自带领伪警察在偏关城乡设卡盘查，逮捕抗日地下交通员，并参与“清乡”行动，烧毁民房数十间。','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','山西','忻州','偏关',null,null,null,null,'','6','伪偏关县警察所所长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5d310abb61d6b05f3915b9d8663628a5','丁鉴修','剑秋',null,'1885','1946','approx','approx','奉天省盖平县','["\\u4E01\\u5251\\u79CB"]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u6C49\\u5978","\\u4F2A\\u6EE1\\u4EA4\\u901A\\u90E8\\u603B\\u957F","\\u4F2A\\u6EE1\\u53C2\\u8BAE\\u5E9C\\u53C2\\u8BAE"]','民国','伪满洲国','丁鉴修，字剑秋，奉天盖平人，清末民初东北地方官员。早年赴日本留学，归国后投身东北地方军政事务，历任奉天省议会议员、东三省巡阅使署参议等职，与张作霖、张学良父子关系密切。九一八事变后，丁鉴修未能坚守民族气节，于1932年参与伪满洲国筹建，出任伪满交通部总长，成为伪满政权核心成员之一。任内积极推行日本殖民统治政策，协助日本侵略者控制东北铁路、公路、港口等交通命脉，为日本掠夺东北资源、镇压抗日力量提供交通保障。后转任伪满参议府参议，继续为伪满傀儡政权效力。1945年日本战败、伪满覆灭后，丁鉴修被苏联红军逮捕，后移交中国政府关押，1946年前后病死于狱中。其一生由东北地方官员沦为汉奸，是民国时期东北地区投敌卖国的典型人物之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:00:52.451781','','白城；白山；经开区；长春；承德；大连；沈阳；阜新；鞍山','通榆；双阳；宽城；绿园；长春高；滦平；旅顺口；大东；新民；浑南；彰武；海州',null,null,null,null,'奉天省盖平县','1','伪满交通部大臣、伪满奉天省省长','0',null,null,null);
