INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5dd91f08163b72115b0379501019b2ce','朱深','博渊',null,'1879','1943','exact','exact','直隶省永清县','["\\u6731\\u535A\\u6E0A"]','["\\u4F2A\\u4E34\\u65F6\\u653F\\u5E9C\\u59D4\\u5458","\\u4F2A\\u534E\\u5317\\u653F\\u52A1\\u59D4\\u5458\\u4F1A\\u59D4\\u5458\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','北洋皖系、伪中华民国临时政府、汪伪政权','朱深（1879—1943），字博渊，直隶永清人。早年留学日本，毕业于东京帝国大学法科，归国后历任京师高等审判厅推事、司法部次长等职，为北洋皖系重要司法官员。1927年任司法总长，次年去职。抗日战争爆发后，朱深于1937年12月参加伪中华民国临时政府，任议政委员会委员、司法部长，成为华北伪政权核心人物之一。1940年汪伪国民政府成立后，伪临时政府改组为华北政务委员会，朱深任委员兼政务厅长，后于1943年2月继王揖唐任华北政务委员会委员长，同年7月病死。朱深长期把持伪政权司法与行政大权，协助日军推行殖民统治，镇压抗日活动，是华北地区重要汉奸头目之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:15:05.018025','','延庆；西城；秦皇岛；廊坊','秦皇岛经开区',null,null,null,null,'直隶省永清县','1','伪华北政务委员会常务委员、伪北京市长','0',null,null,null);
