INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5e4e5e273deef87d833cb86296d66e91','韦焕章',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u5B98\\u5458","\\u6C49\\u5978"]','民国','伪满洲国','韦焕章，生卒年与籍贯均不详，民国时期曾任地方官员。九一八事变后东北沦陷，韦焕章投靠日本侵略势力，出任伪满洲国政权官职，先后担任伪热河省民政厅厅长、伪锦州省省长等职，参与推行日伪统治政策，协助日军维持占领区秩序、征发物资与劳工，为日本殖民统治服务。抗战胜利后，其汉奸身份受到追究，具体结局因史料残缺难以确证。其生平事迹主要散见于伪满洲国官方公报及战后国民政府惩治汉奸的相关档案，因记载零散，早年经历与晚年去向均待进一步考证。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:14:37.522187','','辽阳','',null,null,null,null,'','2','伪满外交部大臣、伪奉天省省长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('5e4e989a1e1c334534b26910de7ba2b4','胡毓坤',null,null,'1895','1946','approx','exact','辽宁辽阳','[]','["\\u5949\\u7CFB\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u519B\\u5934\\u76EE"]','民国','奉系、汪伪政权','胡毓坤，辽宁辽阳人，早年投身奉系军队，历任东北军团长、旅长、师长等职，为张作霖、张学良父子部属。九一八事变后滞留东北，后投靠日本侵略者，参与组建伪军武装。1930年代后期加入汪精卫伪政权，历任汪伪政府军事委员会委员、伪苏豫边区绥靖军总司令等要职，统率伪军配合日军在苏北、豫东地区进行清乡扫荡，镇压抗日武装，残害沦陷区民众。1945年抗日战争胜利后，胡毓坤被国民政府逮捕，以汉奸罪受审。1946年经审判被判处死刑，在南京执行枪决。其一生由奉系军官堕落为汉奸，是抗战时期投敌卖国的典型人物之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:57:12.198028','','昆明；河北；亳州；合肥；安庆；宿州；滁州；芜湖；蚌埠；聊城；九江；廊坊；张家口；信阳；南阳；周口；商丘；开封；新乡；洛阳；郑州；驻马店；宝鸡','呈贡；蒙城；包河；桐城；南谯；淮上；蚌山；茌平；濂溪；尚义；罗山；新野；镇平；项城；商丘经开区；睢阳；兰考；封丘；中原；新密；金水；正阳',null,null,null,null,'辽宁辽阳','2','伪军委会委员、伪军头目','0',null,null,null);
