INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('60a86643605500f18b5cae6a9838358d','郭永福',null,null,null,null,'exact','exact','山西长治潞城；晋城周村','[]','["伪潞城县粮食统制委员会主任", "东沟据点伪警备队长、铁杆汉奸"]','抗日战争时期','','伪职：伪潞城县粮食统制委员会主任；负责为日军强征粮食，压低粮价收购农民余粮，导致当地饥荒，饿死百姓无数。；伪职：东沟据点伪警备队长、铁杆汉奸；罪行：盘踞东沟据点，勾结红枪会，多次下乡扫荡，残害周边村庄百姓，作恶极多。；结局：解放后连同四子一并公审处决','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','山西','长治；晋城','潞城',null,null,null,null,'','5','伪潞城县粮食统制委员会主任','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('60aba21f17ecb763a4e1efaa0d69a8ba','庞炳勋','更陈',null,'1879','1963','exact','exact','直隶省新河县','["\\u5E9E\\u7638\\u5B50","\\u5E9E\\u7638\\u5B50","\\u5E9E\\u7638\\u5B50"]','["\\u897F\\u5317\\u519B\\u5C06\\u9886","\\u56FD\\u6C11\\u9769\\u547D\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u519B\\u5C06\\u9886","\\u56FD\\u6C11\\u515A\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u519B\\u5934\\u76EE","\\u56FD\\u6C11\\u515A\\u519B\\u5C06\\u9886","\\u4F2A\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','西北军、国民革命军、汪伪政权','庞炳勋，字更陈，直隶新河人，早年入北洋军，后投冯玉祥西北军，以骁勇著称，因腿疾人称“庞瘸子”。中原大战后随西北军余部被张学良收编，任国民革命军第四十军军长。抗日战争爆发后率部参加台儿庄战役、徐州会战等，在临沂战役中与张自忠部协同重创日军，升任第二十四集团军总司令、河北省政府主席。1943年4月于河南林县被日军俘虏，旋即投敌，任汪伪政权第五方面军总司令、伪开封绥靖公署主任等职，配合日军“扫荡”抗日根据地。抗战胜利后所部被国民党收编，本人退役闲居。1949年赴台湾，1963年病逝于台北。其由抗日名将沦为汉奸的经历，为民国军事史之典型悲剧。','[]','2026-09-12 13:06:46.288172','2026-09-14 08:28:44.384032','','','',null,null,null,null,'直隶省新河县','2','伪第五方面军总司令','0',null,null,null);
