INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('60f9294ab7e47f44712ba1a92bdd8c40','张海鹏',null,null,'1867','1949','approx','approx','山东济南','["\\u5F20\\u6D77\\u9E4F\\uFF08\\u540C\\u540D\\u8005\\u9700\\u533A\\u5206\\uFF09"]','["\\u5949\\u7CFB\\u519B\\u9600","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u6C49\\u5978"]','民国','奉系、伪满洲国','张海鹏，山东济南人，早年投身行伍，清末民初在东北地方军队中任职，后隶奉系张作霖、张学良父子麾下，官至洮辽镇守使、东北边防军骑兵第一旅旅长等职。九一八事变后，张海鹏于1931年10月公开投敌，率部配合日军进攻黑龙江，参与江桥抗战期间的军事行动，为日军侵占东北充当马前卒。伪满洲国成立后，他历任伪参议府参议、伪热河省省长、伪满洲国侍从武官长等要职，积极推行殖民统治，镇压抗日武装。抗战胜利后，张海鹏被苏军逮捕，后转押至中国，1951年病死于战犯管理所（一说1949年）。其一生由旧军阀沦为汉奸，是东北沦陷时期附逆人物的典型代表。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:24:31.273830','','','',null,null,null,null,'山东济南','2','伪满热河省省长','0',null,null,null);
