INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('6245d3cf712606c70e041d6f454df5db','萧叔宣',null,null,'1893','1946','approx','exact','福建闽侯','["\\u8427\\u5176\\u714A"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u90E8\\u957F","\\u6C49\\u5978"]','民国','汪伪政权','萧叔宣，福建闽侯人，早年入保定陆军军官学校，后赴日本陆军士官学校留学，回国后长期在旧军队中任职。抗日战争爆发后，萧叔宣投靠日本侵略者，加入汪精卫伪政权，历任汪伪政府军事参议院副院长、参军长、军政部部长等要职，成为汪伪军事系统的重要人物之一。他参与整编伪军、配合日军对抗日根据地和沦陷区进行军事控制与镇压，为日本侵华政策服务。抗战胜利后，萧叔宣被国民政府逮捕，以汉奸罪受审，1946年被处决。其一生由旧军人沦为民族罪人，是汪伪政权中典型的投敌卖国者。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:55:52.532384','','九江；宜春；福州；南京','万载',null,null,null,null,'福建闽侯','2','伪陆军部长、伪驻日大使','0',null,null,null);
