INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('645396391020478112635e14b34a0f8b','佚名',null,null,null,null,'exact','exact','镇平县；通城县；上蔡县；西平县/遂平县/上蔡县/舞阳县；蒲圻县（今赤壁市）；安乡县（今属常德）；泌阳县；信阳县；卢氏县；湘乡县；昌乐；潍坊各地；安丘；枝江市；原阳县；鄂城泽林镇；汝南县；随县（伪军）；衡阳地区；确山县；西平县；孝感花园镇；襄阳地区；南阳县；罗山县；应城县；洪江市；江华县；方城县；宜都市；京山县；岳阳；烟台（芝罘）；房县；博爱；虞城；益阳县；远安县；海阳县；驻马店地区；烟台市；淮阳县；滍阳（今属平顶山）；孟县；邵阳县黑田铺洪桥；郾城/漯河；南阳市区；荆门地区；临颍县；浠水县；商丘；当阳市；辰溪县；资兴县（今资兴市）；潍县；洞口县月溪（怀化洪江老兵参与）','[]','["彭营汉奸", "汉奸（带路者）", "汉奸", "曲屯街维持会会长", "西平、上蔡、遂平、舞阳四县日伪军联防司令部", "汪伪“和平救国军第3师”（和三师）", "汉奸（告密者）", "伪维持会成员", "伪信阳县政府官员", "汉奸、伪军", "汉奸密探", "伪昌乐县长（后期）", "伪乡长、伪保长", "伪安丘保安大队中队长", "枝江汉奸", "伪军部队", "告密汉奸", "伪维持会、伪军清剿队成员", "伪和平建国绥靖军第十一师", "汉奸分子", "汉奸（带路）", "伪维持会、皇协军", "伪军（3名）", "伪维持会、伪保安队基层头目", "南阳城郊维持会人员", "伪军（汉奸队伍）", "汉奸（信号员）", "平民", "国民党江华地方当局", "维持会成员", "宜都汉奸", "汉奸告密者", "汉奸（施放信号）", "日军芝罘陆军特务机关汉奸特务队（31名）", "国民党第五战区的汉奸队伍", "博爱维持会成员", "虞城县伪县长", "日军便衣特务", "远安汉奸", "汉奸（密告者）", "汉奸武装（皇协军）", "伪鲁东道（后改登州道）各级官员", "淮阳伪县长", "滍阳街维持会负责人", "孟县维持会成员", "楼子王维持会负责人", "洪桥维持会成员", "日伪汉奸机构成员", "自警团成员", "曲屯街维持会副会长", "南阳复兴委员会成员", "伪维持分会会长", "五龙庙维持会负责人", "临颍维持会成员", "日伪浠水县长", "汉奸组织", "汉奸乡长", "伪豫东道公署各级官员", "当阳汉奸组织", "告密者", "汉奸（引路者）", "汪伪军十二师骑兵团二营（汉奸队伍）", "日伪特务", "帮日本人的汉奸"]','抗日战争时期','','伪职：彭营汉奸；罪行：镇平县彭营一带汉奸，为虎作伥，替日军搜集情报，带日军到处扫荡，群众恨之入骨；结局：被抗日游击队诱捕后活埋于村南大沟内；伪职：汉奸（带路者）；罪行：1938年11月日军从崇阳向通城进攻时，有汉奸为日军带路；伪职：汉奸；罪行：上蔡县杨集惨案相关汉奸。1944年5月上蔡失陷后，高庙乡自卫队威胁日军安全，遭日伪军报复，110名乡自卫队员惨死；伪职：曲屯街维持会会长；罪行：镇平县曲屯沦陷后，日军网罗地痞流氓二百多人充当汉奸，成立曲屯街、五龙庙、楼子王三个维持会；伪职：西平、上蔡、遂平、舞阳四县日伪军联防司令部；罪行：抗日战争时期，日伪军在西平县合水镇成立了西平、上蔡、遂平、舞阳四县日伪军联防司令部，对相距50里外的豫中抗日根据地构成直接威胁；伪职：汪伪“和平救国军第3师”（和三师）；罪行：盘踞蒲圻的汪伪汉奸部队，原为国民党军第九战区部队，后投敌当了汉奸，鱼肉百姓，在蒲圻遗臭万年；伪职：汉奸（告密者）；罪行：安乡县三度陷落日军之手。抗日战士陈辉（常德籍）在河北执行任务后返回时因汉奸告密被日军包围；伪职：伪维持会成员；罪行：日军侵犯泌阳后，利用本地少数汉奸建立临时性傀儡政权——维持会，以维护地方秩序为名，统治沦陷区人民；伪职：伪信阳县政府官员；罪行：日本人扶植汉奸成立了伪县政府，并在街头举行庆祝大会；伪职：汉奸、伪军；罪行：1945年5月，日军“铃木师团”和汉奸、伪军约万余人由陕州曹庙方面分两路进攻卢氏；伪职：汉奸密探；罪行：湘乡自卫团第六联乡大队队员沈绍在战斗中腿部负伤在家养伤，被汉奸密探得知后报告日军，当夜遭日军夜袭队抓捕；伪职：伪昌乐县长（后期）；罪行：汉奸县长，曾多次劝降抗日烈士出任伪职，遭烈士破口大骂；伪职：伪乡长、伪保长；罪行：日伪在潍坊各地推行保甲制度，设立大量伪乡、保长，为日军征粮派款、搜捕抗日人员；结局：部分被镇压，部分待考；伪职：伪安丘保安大队中队长；罪行：谭培东部下另两个中队长；伪职：枝江汉奸；罪行：抗战胜利后，枝江等县处决了一批汉奸；结局：被处决；伪职：伪军部队；罪行：1945年6月，勾结原武、阳武两地日伪军和其他杂牌股匪共2000多人，在原阳县官厂乡判官村一带对原阳县抗日民主政府及其武装发动大规模进攻；伪职：告密汉奸；罪行：1942年9月16日向日军告密，致使大山寺程姓祠堂被日军烧毁，寺湾湖9位村民被枪杀；伪职：伪维持会、伪军清剿队成员；罪行：1944年3月汝南县城第三次沦陷后，日寇在此组建了汉奸伪维持会和伪军清剿队为其效劳；伪职：伪和平建国绥靖军第十一师；罪行：该部由国民党桂系军队败退时遗留的溃兵编成，共300余人，汪伪政府成立前为“皇协军”，其余为随县附近招收的散兵游勇和土匪；伪职：汉奸分子；罪行：1940年5月1日衡阳锄奸讨逆运动中，各单位锄奸队清出的汉奸分子共105人；结局：1940年5月1日公布并发布通缉令；伪职：汉奸（带路）；罪行：1944年，一伙日本鬼子在汉奸的带领下来到确山县古城乡李湾村，扬言让村里人交出一个名唤郭莲的妇女，否则就要对全体村民下手；伪职：伪维持会、皇协军；罪行：西平陷落后，日寇在县城和各乡镇建立了维持会，并成立1个团和3个营的“皇协军”，采取以华制华的办法，镇压蹂躪和奴化西平人民；伪职：伪军（3名）；罪行：1943年正月十三日跟随陈小汉在松林湾抢劫百姓财物；结局：被丁庆江等锄奸队员打翻在地；伪职：伪维持会、伪保安队基层头目；罪行：襄阳各乡镇有大量伪维持会、伪保安队基层头目，依仗日军撑腰，抓壮丁、征粮，祸害乡里；结局：作恶深重的战时即遭锄奸处置；胁从入伙、罪行较轻者战后教育宽大处理；伪职：南阳城郊维持会人员；罪行：日军在南阳城附近遍设维持会，网罗流氓、恶棍、惯匪组织伪军；伪职：伪军（汉奸队伍）；罪行：抗日战争时期罗山境内有汉奸武装活动；伪职：汉奸（信号员）；罪行：1938年10月27日应城遭日机轰炸时，城内汉奸打信号为日机指引目标，致使轰炸异常精准；伪职：平民；罪行：1945年春在洪江大湾塘被卫兵当作汉奸抓起来关了一晚；结局：后经熟人证明释放（非汉奸）；伪职：国民党江华地方当局；罪行：抗战期间，江华县地方当局被指有汉奸罪行。共产党员韦汉曾向省政府申诉，历数江华县地方当局的汉奸罪行；结局：韦汉被国民党江华地方当局以“匪首”罪名逮捕杀害；伪职：维持会成员；罪行：日军在独树镇设立维持会、自警团、蓝工队3个汉奸组织，有武装三四百人。维持会、自警团驻守镇内；伪职：宜都汉奸；罪行：抗战胜利后，宜都等县处决了一批汉奸；结局：被处决；伪职：汉奸告密者；罪行：1943年3月28日，因汉奸告密，新四军五师四十三团营长林水川部驻地方家岩子突然遭到日伪军包围，吴堰岭区委书记黄连、京钟武工队队长熊庆璋等27位同志牺牲；伪职：汉奸（施放信号）；罪行：日军轰炸岳阳时施放信号为日机指引目标；结局：被保安一区司令部处决；伪职：日军芝罘陆军特务机关汉奸特务队（31名）；罪行：日军芝罘陆军特务机关汉奸特务队31名特务；结局：全部死于日军宪兵的机枪和刺刀下；伪职：国民党第五战区的汉奸队伍；罪行：房县罗坪一带活动，1944年前后围堵为新四军筹粮的抗日人员；伪职：博爱维持会成员；罪行：日军侵占博爱后，当地汉奸成立维持会为日军服务；伪职：虞城县伪县长；罪行：虞城县伪县长，带领伪军固守县城，经常派小股部队搞伪化宣传，骚扰群众，破坏抗日民族统一战线；伪职：日军便衣特务；罪行：1944年益阳沦陷后，有2名汉奸便衣特务随日军活动，人称“孙大麻子”的铁杆汉奸拎枪为日军争功；伪职：远安汉奸；罪行：远安县抗战时期有日伪汉奸活动；伪职：汉奸（密告者）；罪行：将自卫队队长雷长德密告敌伪；伪保安队将雷长德抓去；伪职：汉奸武装（皇协军）；罪行：日军在各县城建立日伪据点，组织“维持会”，成立“皇协军”，进行野蛮的“清乡”和“扫荡”，对驻马店地区人民进行残暴的殖民统治；伪职：伪鲁东道（后改登州道）各级官员；罪行：伪鲁东道管辖福山等县；辖济南、烟台两市及103个县级伪机关；伪职：淮阳伪县长；罪行：日寇抓捕张润生及其大女儿后，让伪县长等人作人质担保，放出了张润生；伪职：滍阳街维持会负责人；罪行：1944年6月，日军发现一名日军队长尸体后，当地维持会汉奸纷纷出动，挨家挨户彻查，为日军搜寻凶手；伪职：孟县维持会成员；罪行：1938年1月日军侵占孟县县城后，收罗扶持汉奸拼凑维持会，两个月后改为伪县政府；伪职：楼子王维持会负责人；罪行：镇平县曲屯地区三个维持会之一；伪职：洪桥维持会成员；罪行：随日军之夫系黑田铺洪桥维持会所派，其搜括之伎俩较敌尤加倍；伪职：日伪汉奸机构成员；罪行：漯河沦陷后，一些丧失民族气节的人向日军屈膝，成立了日伪汉奸机构维持会、特务情报队和伪警察局，帮助日军镇压人民。伪军河南绥靖军司令寇英杰派军长邱三宁来漯河抢占地盘、扩充势力；伪职：自警团成员；罪行：日军在独树镇设立的汉奸组织之一；伪职：曲屯街维持会副会长；罪行：曲屯街维持会设有会长、副会长、秘书、武装队长、军事教官等职；伪职：南阳复兴委员会成员；罪行：1945年5月，日伪政权成立“南阳复兴委员会”，沿袭国民党旧制设立区、乡、保甲组织，以南阳城关为据点，四出“讨伐”、扫荡，实行“三光”政策；伪职：伪维持分会会长；罪行：日军占领荆门后，在荆门成立“维持总会”和24个“维持分会”，各分会负责人均为汉奸；结局：1945年9月汪伪政权瓦解；伪职：五龙庙维持会负责人；罪行：镇平县曲屯地区三个维持会之一；伪职：临颍维持会成员；罪行：1944年5月2日临颍沦陷后，日军即建立军政部和维持会。日伪在临颍共打死农民2350人，逼死12333人；奸淫妇女2139人，致死80人；伪职：日伪浠水县长；罪行：1938年日军进入浠水后设立日伪浠水县政府；结局：1945年日本投降后撤销；伪职：汉奸组织；罪行：1941年敌在商丘成立汉奸组织“乐园部队”，1941年下半年又成立外围组织“和猛工作队”，触角伸到永夏地区，在县、区、镇、保、甲设各级指挥部，配合日寇搞“治安强化”，监视、逮捕和杀害共产党人和进步人士；伪职：汉奸乡长；罪行：侵华日军为控制北山抗日根据地中心地段，连派7个汉奸到下胡家集任乡长；结局：北山抗日武装在叶云领导下铲除耳目，这些汉奸无一漏网；伪职：伪豫东道公署各级官员；罪行：伪豫东道公署设于商丘，统辖商丘、永城、夏邑、虞城、柘城、宁陵、睢县、民权等县伪政权，推行保甲制度，配合日军“治安强化”运动，横征暴敛；伪职：当阳汉奸组织；罪行：1941年5月29日，当阳汉奸组织欢迎日军。当阳是宜昌市下辖县级市，抗战时期有汉奸组织活动；伪职：告密者；罪行：向日军告密海军水雷所位置，致使日军出动209架次飞机轰炸辰溪22次，炸毁房屋1232栋，伤亡军民3770余人；伪职：汉奸（引路者）；罪行：1945年2月12日，为日军引路找到避居山中的辛亥革命元老程子楷；伪职：汪伪军十二师骑兵团二营（汉奸队伍）；罪行：1942年驻扎在中山铺（今信阳县境），经常在信罗边根据地抢粮；结局：1942年4月被信罗边县公安局手枪队配合500多名民兵夜袭，毙敌20余人，俘敌120余人，缴获战马20匹、机枪3挺、步枪94支、迫击炮1门；伪职：日伪特务；罪行：日军在潍县设有大量汉奸特务网络，包括“宣抚班”等机构；伪职：帮日本人的汉奸；罪行：在雪峰山战役中帮日本人做事，被74军57师捉住；结局：被74军57师官兵用刺刀处死','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','河北','','',null,null,null,null,'','3','彭营汉奸','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('645be9e5d58e90b2b6c73efa66bf64b5','朱深（重复？不，另列）',null,null,null,null,'exact','exact','河北廊坊','[]','["伪华北政务委员会常务委员"]','抗日战争时期','','伪职：伪华北政务委员会常务委员；参与决策对冀中抗日根据地的“毁灭性扫荡”，包括廊坊地区。','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','河北','廊坊','',null,null,null,null,'','7','伪华北政务委员会常务委员','0',null,null,null);
