INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('65b47d3e475a47ad6fd45d82a200c885','萧瑞臣',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6CB3\\u5357\\u7701\\u653F\\u5E9C\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','汪伪政权','萧瑞臣，生卒年与籍贯不详，民国时期政治人物。抗日战争进入相持阶段后，日本侵略者为巩固对华北占领区的统治，扶植傀儡政权。1938年前后，萧瑞臣投靠日军，参与伪河南省政权的筹建与运作，出任伪河南省政府省长（一说伪河南省公署省长），成为日军在河南实施殖民统治的重要代理人。任内秉承日本占领军意旨，推行保甲连坐、征发民夫与粮秣、配合日军对抗日根据地实行经济封锁与扫荡，搜刮沦陷区物资以支持侵华战争，并镇压抗日爱国力量，对河南民众造成深重灾难。其政权完全依附于日军特务机关与华北伪政权，缺乏独立行政能力。抗战胜利后，萧瑞臣作为汉奸被国民政府逮捕审判，具体结局与生卒年月史料记载不一，尚待进一步考证。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:48:46.199126','','黄南；安阳；新乡','河南；文峰；林州；原阳；封丘；延津',null,null,null,null,'','2','伪河南省政府省长','0',null,null,null);
