INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('6707131fc404251119bf49dc98e65aee','马鸿逵','少云',null,'1892','1970','exact','exact','甘肃河州（今甘肃省临夏回族自治州临夏市）','["\\u9A6C\\u5C11\\u4E91"]','["\\u56FD\\u6C11\\u515A\\u9646\\u519B\\u4E0A\\u5C06","\\u5B81\\u590F\\u7701\\u653F\\u5E9C\\u4E3B\\u5E2D","\\u897F\\u5317\\u519B\\u9600"]','民国','国民党西北马家军（宁马）','马鸿逵，字少云，甘肃河州人，西北马家军宁马派首领。早年入甘肃陆军学堂，后投冯玉祥国民军，历任师长、军长。1929年叛冯投蒋，1933年出任宁夏省政府主席，主政宁夏十七年，集军政大权于一身，实行保甲连坐、苛捐杂税与严密特务统治，人称“宁夏王”。抗战期间任第八战区副司令长官兼第十七集团军总司令，消极抗日、积极反共，封锁陕甘宁边区。解放战争中任西北军政长官公署副长官、宁夏兵团司令官，1949年9月宁夏战役中主力被歼，携眷逃往台湾，后赴美国定居，1970年病逝于洛杉矶。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:25:18.530293','','大同；平凉','云冈；静宁',null,null,null,null,'甘肃河州韩家集阳洼山村','2','宁夏省政府主席、国民党军第八战区副司令长官兼第十七集团军总司令','0',null,null,null);
