INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('6ccfd55b774e47108f5ddae8f2143e97','孙铭九',null,null,'1909','2000','approx','approx','辽宁新民','["\\u5B59\\u94ED\\u4E45"]','["\\u4E1C\\u5317\\u519B\\u519B\\u5B98","\\u897F\\u5B89\\u4E8B\\u53D8\\u53C2\\u4E0E\\u8005","\\u5C11\\u58EE\\u6D3E\\u9996\\u9886"]','民国','东北军','孙铭九，辽宁新民人，东北军青年军官，曾任张学良卫队营营长，为东北军少壮派核心人物之一。1936年西安事变中，他率部参与临潼扣蒋行动，是事变的关键执行者之一。事变和平解决后，张学良送蒋返南京被扣，东北军内部围绕营救张学良问题产生和战分歧，孙铭九等少壮派主张武力营救，与元老派王以哲等发生激烈冲突。1937年2月，孙铭九等派人刺杀东北军元老派将领王以哲，酿成二二事件，导致东北军内部严重分裂，随后孙铭九离开东北军。抗日战争期间，孙铭九曾一度投靠汪伪政权，担任伪职，战后被国民政府逮捕，后获释。中华人民共和国成立后，孙铭九曾任上海市人民政府参事等职，晚年撰写回忆录，2000年前后在上海去世。其一生功过交织，既是西安事变的参与者，也因二二事件和附伪经历而备受争议。','[]','2026-09-15 06:51:41.790521','2026-09-15 06:51:59.035904','',null,null,null,null,null,null,'辽宁新民',null,null,'0',null,null,null);
