INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('723a463a063d96d9de051a85ced89ffe','胡家凤',null,null,'1893','1962','approx','approx','江西南昌','[]','["\\u56FD\\u6C11\\u515A\\u5B98\\u5458","\\u6C5F\\u897F\\u7701\\u4E3B\\u5E2D","\\u6559\\u80B2\\u5BB6"]','民国','国民党','胡家凤（约1893—约1962），江西南昌人，民国时期国民党官员、教育家。早年毕业于江西法政专门学校，后赴日本留学，入明治大学研习政治经济。归国后历任江西省立第一中学校长、江西省教育厅厅长等职，致力于地方教育改革。抗日战争期间，随江西省政府辗转后方，坚持战时教育。1948年任江西省政府委员兼教育厅厅长，1949年任江西省政府主席，不久去职。后赴台湾，曾任台湾当局教育部门职务。晚年淡出政坛，约1962年病逝。其一生跨越清末、民国与抗战时期，是近代江西教育与政治的重要人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:52:07.922239','','南昌','新建',null,null,null,null,'江西南昌','2','伪江西省政府委员、伪南昌市市长','0',null,null,null);
