INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('7797183518662c2e276182c10613e23c','杜锡钧',null,null,'1880','1945','approx','approx','直隶故城','["\\u675C\\u9521\\u94A7"]','["\\u4F2A\\u6E56\\u5317\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u5317\\u6D0B\\u5C06\\u9886"]','民国','北洋军阀（直系）→汪伪政权','杜锡钧，直隶故城人，清末投北洋新军，后入保定军官学堂，毕业后在直系军阀中历任营长、团长、旅长等职，1920年代曾任湖北督军署参谋长、湖北陆军第二师师长等，为直系在湖北的重要军事人物。北伐后一度闲居。抗日战争爆发后，武汉沦陷，杜锡钧于1939年附逆投敌，出任汪伪政权湖北省政府主席兼保安司令，成为汪伪在华中地区的重要傀儡头目。任内协助日军推行治安强化运动，征粮拉夫，镇压抗日力量，搜刮民财，危害甚巨。1945年抗战胜利前夕，杜锡钧在武汉病死，未及受到审判。其一生由北洋旧军人沦为汉奸，是民国时期投敌卖国的典型人物之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:21:47.132278','','晋中；徐州；唐山；廊坊；石家庄；秦皇岛；信阳；商丘；开封；沧州','左权；唐山海港经开区；开平；滦南；路南；迁安；遵化；固安；石家庄循环化工园；抚宁；昌黎；海港；秦皇岛经开区；信阳高；民权；禹王台',null,null,null,null,'直隶故城','1','伪华北政务委员会绥靖总署督办','0',null,null,null);
