INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('780351ade3234ed304781d27bd57883d','沈鸿烈','成章','无','1882','1969','exact','exact','湖北天门','["\\u6C88\\u6210\\u7AE0"]','["\\u4E1C\\u5317\\u6D77\\u519B\\u521B\\u5EFA\\u4EBA","\\u9752\\u5C9B\\u5E02\\u5E02\\u957F","\\u5C71\\u4E1C\\u7701\\u653F\\u5E9C\\u4E3B\\u5E2D","\\u56FD\\u6C11\\u653F\\u5E9C\\u5B98\\u5458"]','民国','国民政府（东北海军、政学系）','沈鸿烈，字成章，湖北天门人，1882年生。早年赴日本海军学校留学，加入同盟会。归国后投身海军，历任北洋政府海军部科长、东北海军副总司令等职，创建东北海军，为张作霖、张学良所倚重。1929年任青岛特别市市长，主政六年，推动市政建设与教育发展。1938年任山东省政府主席、省保安司令，兼国民党山东省党部主任委员，在鲁坚持抗战，组建游击武装。1941年调任国民政府农林部长，后任党政工作考核委员会秘书长等职。1949年赴台湾，曾任台湾当局领导人办公室政策顾问。1969年在台北病逝，终年87岁。沈鸿烈一生历经清末、民国与抗战，由海军将领转型为地方行政长官，在青岛市政建设与山东抗战中有一定建树，但其反共立场亦为历史所记。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:40:41.533543','','北辰','',null,null,null,null,'湖北天门','2','伪天津特别市公署参事','0',null,null,null);
