INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('8414d98cc2e395eff8b169398928fc8f','高凌霨','泽畲',null,'1868','1939','approx','approx','直隶天津','["\\u9AD8\\u6CFD\\u7572"]','["\\u4F2A\\u5929\\u6D25\\u7279\\u522B\\u5E02\\u5E02\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u5317\\u6D0B\\u653F\\u5BA2"]','民国','北洋政府、皖系、直系、汪伪政权','高凌霈（1868—1939），字泽畲，直隶天津人，清末举人出身，北洋时期政客。民国初年历任直隶省议会议员、国会众议院议员，后依附皖系、直系军阀，曾任北洋政府内务部次长、农商总长、财政总长等职，并一度代理国务总理。1924年直系失败后去职闲居天津。抗日战争爆发后，天津沦陷，高凌霈于1937年12月出任伪天津特别市市长，成为日本侵略者扶植的地方傀儡政权头目，协助日军维持治安、征敛物资、推行奴化教育，为虎作伥。1939年病死于天津任上。其一生由清末士绅而北洋政客，最终堕落为汉奸，为后世所唾弃。','[]','2026-09-12 13:06:46.288172','2026-09-15 09:04:09.577953','','通州；北辰；南开；和平；河西；常德；武汉；万州；沙坪坝；天津','津；江岸',null,null,null,null,'直隶天津','2','伪天津特别市市长','0',null,null,null);
