INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('8447ef63579f12e9617acbec90f1b6c1','徐箴',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6D59\\u6C5F\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','抗日战争时期','汪伪政权','徐箴，生卒年及籍贯不详，是抗日战争时期汪伪政权中的地方官员。据现有史料，徐箴曾在汪伪浙江省政府中担任省长（或代省长、伪职首长）一类职务，属于汪精卫伪国民政府系统内的地方行政头目。汪伪政权于1940年3月在南京成立后，陆续在江苏、浙江、安徽、湖北等沦陷区设立伪省政府，徐箴即在这一背景下出任伪浙江省要职，协助日军维持沦陷区统治、推行伪化政策，为日本侵略者搜刮物资、镇压抗日力量。由于徐箴并非汪伪核心决策层人物，且相关档案散佚，其具体任职时间、籍贯、字号、生卒年月及家庭情况均缺乏可靠记载，仅能确认其作为伪浙江省长的身份。抗战胜利后，国民政府对其是否追究、结局如何，亦未见明确史料。','[]','2026-09-12 13:06:46.288172','2026-09-15 09:02:11.439019','','','',null,null,null,null,'','2','伪浙江省长','0',null,null,null);
