INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('89b22b41f29600bbe902f27c542590ea','额勒登格',null,null,null,null,'unknown','unknown','内蒙古哲里木盟','[]','["\\u8499\\u53E4\\u738B\\u516C","\\u4F2A\\u5174\\u5B89\\u897F\\u7701\\u7701\\u957F","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458"]','民国','蒙古王公、伪满洲国','额勒登格，蒙古族，出身哲里木盟科尔沁部贵族，具体生卒年与早年经历史料记载不详。九一八事变后，日本关东军侵占中国东北，扶植伪满洲国。额勒登格投靠日伪，出任伪满洲国兴安西省省长，成为日本侵略者统治内蒙古东部地区的傀儡官员。兴安西省管辖今内蒙古昭乌达盟一带，是伪满推行蒙地殖民统治、掠夺资源、镇压抗日力量的重要行政区。额勒登格任内秉承日本关东军旨意，推行日伪政令，协助征发劳役、物资，配合日伪对当地蒙古族民众的统治与压制，其行为属于投敌附逆、为虎作伥。抗战胜利后，伪满洲国覆灭，额勒登格下落及结局史料缺乏明确记载。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:43:36.358396','','','',null,null,null,null,'','2','伪兴安西省省长','0',null,null,null);
