INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('908edb1099c84cd216af3b1eacf1568f','谢介石',null,null,'1878','1954','approx','approx','台湾新竹','["\\u8C22\\u4ECB\\u77F3"]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5916\\u4EA4\\u5B98","\\u6C49\\u5978","\\u53F0\\u7C4D\\u653F\\u5BA2"]','民国','伪满洲国','谢介石，台湾新竹人，早年留学日本，毕业于明治大学法律科，通晓日语与俄语。清末民初赴中国大陆活动，曾参与张勋复辟，后投靠日本关东军。1932年伪满洲国成立后，出任首任外交部总长，成为伪满初期核心外交官员，代表伪满与日本签订多项卖国协定，并推动伪满获得部分国家承认。1935年转任伪满驻日大使，后任参议府参议等职。他身为台湾人却效忠日本侵略势力，协助日本巩固对东北的殖民统治，是典型的汉奸人物。抗战胜利后，谢介石被苏联红军逮捕，后引渡回中国，1954年病死于狱中。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:35:24.530321','','昆明；长春；伊春；哈尔滨；新竹','呈贡；宽城；绿园；长春高；丰林；松北',null,null,null,null,'台湾新竹','1','伪满洲国外交部总长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('90949a2d34ce143ac39cc497bfbed4fb','张淦',null,null,'1897','1949','approx','exact','广西桂林','[]','["\\u56FD\\u6C11\\u515A\\u519B\\u5C06\\u9886","\\u6842\\u7CFB\\u5C06\\u9886"]','民国','中国国民党桂系','张淦，广西桂林人，早年入广西陆军讲武堂，后投身桂系军队，为李宗仁、白崇禧部属。历任排长、连长、营长、团长等职，参加北伐战争。抗日战争时期，任国民革命军第四十八军第一七六师师长、第四十八军副军长等职，率部参加淞沪会战、徐州会战、武汉会战及桂南会战等战役，在桂南会战中与日军激战，所部伤亡惨重。1944年任第二十一集团军副总司令，参加豫湘桂战役。1949年任华中军政长官公署副长官兼第三兵团司令官，率部在广西抵抗解放军，同年12月在广西博白被俘，后于1950年病逝于战犯管理所。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:24:24.434805','','六安；南宁；桂林','裕安；恭城',null,null,null,null,'广西桂林','2','国民党桂系将领','0',null,null,null);
