INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('9457bc839538db5bdb1293d57b911aa2','孙良诚','良臣',null,'1893','1951','exact','exact','直隶天津','["\\u5B59\\u826F\\u81E3"]','["\\u897F\\u5317\\u519B\\u5C06\\u9886","\\u4F2A\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','西北军、汪伪政权、国民党','孙良诚，字良臣，天津静海人，早年入冯玉祥西北军，累升至军长、山东省政府主席，为西北军“五虎将”之一。中原大战后随冯玉祥下野，后投靠蒋介石，任军事参议院参议等职。抗日战争爆发后，孙良诚部在冀鲁豫一带活动，1942年率部投靠汪伪政权，任伪第二方面军总司令、伪苏北绥靖公署主任等职，驻防扬州、泰州、盐城等地，配合日军“扫荡”抗日根据地，危害甚大。抗战胜利后，孙良诚部被国民党收编，任新编第六路军总司令，后改任第一绥靖区副司令官。1948年淮海战役中，孙良诚率部投诚，后曾参与策反刘汝明未果。1951年病逝于南京。其一生由西北军名将沦为汉奸，晚节不终，历史评价以负面为主。','[]','2026-09-12 13:06:46.288172','2026-09-14 08:32:32.876840','','常德；六安；阜阳；聊城；菏泽；泰州；淮安；连云港；唐山；邢台；宝鸡；天津','津；神木；阜南；颍州；茌平；高港；灌云',null,null,null,null,'直隶天津','2','伪第二方面军总司令','0',null,null,null);
