INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('960cd32012ce1ff05df8eb806b963b45','熊式辉','天翼','雪松','1893','1974','exact','exact','江西省南昌县','["\\u718A\\u5929\\u7FFC","\\u96EA\\u677E"]','["\\u56FD\\u6C11\\u515A\\u9AD8\\u7EA7\\u5C06\\u9886","\\u6C5F\\u897F\\u7701\\u4E3B\\u5E2D","\\u653F\\u5B66\\u7CFB\\u8981\\u5458"]','民国','中国国民党','熊式辉，字天翼，号雪松，江西南昌人。早年入江西陆军小学、南京陆军中学，1911年参加辛亥革命，后入保定军校第二期，旋赴日本陆军大学深造。1924年回国任滇军干部学校教官，后投奔广东革命政府，任国民革命军第十四军党代表、师长，参加北伐。1928年后历任淞沪警备司令、江浙皖三省剿匪总指挥、江西省主席等职，主赣十年，推行保甲、清剿红军，同时兴办教育、建设赣南。抗战时期任军事委员会委员长南昌行营办公厅主任、驻美军事代表团团长、中央设计局秘书长。抗战胜利后任东北行营主任兼东北保安司令长官，主持东北接收，因军事失利去职。1949年赴香港，后迁台湾，曾任总统府战略顾问。1974年病逝于台北。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:45:11.092845','','普洱；九江；吉安；宜春；抚州；新余；景德镇；赣州；鹰潭','西；修水；德安；柴桑；浔阳；泰和；青原；万载；奉新；宜丰；袁州；靖安；高安；宜黄；分宜；乐平；会昌；宁都；章贡；余江',null,null,null,null,'江西省南昌县','2','伪江西省长','0',null,null,null);
