INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('994cf66c28a34e7c0cf1cb33bd64524b','丁默邨',null,null,'1901','1947','approx','exact','湖南常德','["\\u4E01\\u9ED8\\u6751"]','["\\u6C6A\\u4F2A\\u7279\\u5DE5\\u5934\\u76EE","\\u4F2A\\u653F\\u5E9C\\u90E8\\u957F","\\u6C49\\u5978"]','民国','汪伪政权','丁默邨，湖南常德人，早年加入中国共产党，后叛投国民党，入国民党特务组织，曾任军事委员会调查统计局第三处处长。抗日战争爆发后，1939年投靠日本侵略者，与李士群等在上海组建汪伪特工总部（极司菲尔路76号），任主任，大肆捕杀抗日志士和爱国群众，成为汪伪政权特务头目。后历任汪伪国民党中央执行委员会常务委员、社会部部长、浙江省政府主席等伪职，为虎作伥，罪行累累。抗战胜利后被捕，1947年以汉奸罪被判处死刑，在南京执行枪决。','[]','2026-09-12 13:06:46.288172','2026-09-14 02:53:55.450757','','常德；盐城；虹口；合肥；普洱；芜湖；蚌埠；常州；淮安；镇江；丽水；杭州；温州；湖州；舟山','阜宁；庐阳；西；芜湖经开区；淮上；淮安经开区；丹徒；青田；桐庐；淳安；瑞安；嵊泗',null,null,null,null,'湖南常德','1','伪浙江省长','0',null,null,null);
