INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('99638c644ffd4bd180d9a5b9b2c9711f','赵毅',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u6EE1\\u5B98\\u5458","\\u8B66\\u52A1\\u79D1\\u957F"]','抗日战争时期','伪满洲国','赵毅，生卒年及籍贯不详，活跃于伪满洲国时期。据地方志及伪满档案记载，曾任伪满勃利县警务科长。勃利县位于今黑龙江省七台河市，伪满时期为三江省所辖，其警务科负责维持地方治安、镇压抗日活动、编查户口、征收捐税等。赵毅作为警务科长，统辖伪警察队伍，执行日伪当局的“治安肃正”政策，参与搜捕抗日志士、推行保甲连坐、掠夺物资等行动，是日本侵略者统治勃利地区的帮凶。1945年日本投降后，伪满政权覆灭，赵毅下落不明，其具体罪行与结局因史料匮乏而难以详考。','[]','2026-09-15 08:32:55.627510','2026-09-15 08:33:07.859040','',null,null,null,null,null,null,'',null,null,'0',null,null,null);
