INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('9d47bd136f436e9d42fe5a3f46a6df5e','赵侗',null,null,'1912','1939','approx','exact','辽宁岫岩','["\\u8D75\\u540C","\\u8D75\\u4F97\\uFF08\\u4E5F\\u4F5C\\u8D75\\u540C\\uFF09"]','["\\u6297\\u65E5\\u4E49\\u52C7\\u519B\\u5C06\\u9886","\\u516B\\u8DEF\\u519B\\u5C06\\u9886"]','抗日战争时期','东北抗日义勇军、八路军','赵侗，辽宁岫岩人，满族，生于1912年前后。九一八事变后，在东北组织抗日武装，任东北民众自卫军第二十八路军司令等职，率部在辽东三角地带开展抗日游击战。1936年加入中国共产党。全面抗战爆发后，所部改编为八路军晋察冀军区第五支队，任司令员，参与创建平西抗日根据地。1939年，在河北涞水一带与日军作战中牺牲，年仅二十七岁。赵侗是东北抗日义勇军和八路军早期抗日将领，其抗日事迹在党史、军史中有记载。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:58:17.616080','','河北；保定；唐山；沧州；石家庄；渭南','唐县；安国；定州；莲池；沧州渤海；裕华；辛集；华州',null,null,null,null,'辽宁岫岩','2','伪华北民众自治军总司令','0',null,null,null);
