INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('9fe0fb5c4516c1900ec222b249226d53','梁鸿志','众异','无','1882','1946','exact','exact','福建长乐','["\\u6881\\u4F17\\u5F02"]','["\\u4F2A\\u884C\\u653F\\u9662\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','北洋皖系、汪伪政权','梁鸿志（1882—1946），字众异，福建长乐人，清末举人。早年入北洋幕府，为皖系段祺瑞亲信，曾任安福国会参议院议员、段祺瑞执政府秘书长。北洋覆灭后寓居上海。抗日战争爆发后，1938年3月在日本扶持下于南京成立“中华民国维新政府”，任行政院长，与日本签订多项卖国协定，出卖华中资源与主权。1940年汪精卫成立伪国民政府后，梁任监察院长、立法院长等职，继续为日军侵华服务。抗战胜利后被捕，1946年以汉奸罪被判处死刑，同年11月在上海提篮桥监狱执行枪决。其一生由北洋政客堕落为民族罪人，是近代史上臭名昭著的汉奸之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:23:03.154603','','昆明；福州；柳州；西安','呈贡；长乐；柳南',null,null,null,null,'福建福州','1','伪维新政府行政院长','0',null,null,null);
