INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('a35284ede6906611bfe648fedf7f0328','王柏龄','茂如',null,'1889','1942','exact','exact','江苏江都','["\\u738B\\u8302\\u5982"]','["\\u56FD\\u6C11\\u515A\\u5C06\\u9886","\\u9EC4\\u57D4\\u519B\\u6821\\u6559\\u5B98","\\u519B\\u4E8B\\u6559\\u80B2\\u5BB6"]','民国','中国国民党','王柏龄，字茂如，江苏江都人，中国国民党早期军事将领、军事教育家。早年入保定陆军速成学堂，后赴日本陆军士官学校留学。回国后投身革命，参与辛亥革命及护国、护法诸役。1924年黄埔军校创办时，任教授部主任，后任教育长，负责军事教育，为黄埔系重要人物。北伐战争期间，任国民革命军第一军副军长、第一师师长等职，参加北伐。后因作战失利去职，转任军事教育及文职。抗日战争时期，曾任国民政府军事委员会高级参谋等职。1942年在重庆病逝。王柏龄长期从事军事教育，对黄埔军校早期建设有所贡献，但其军事指挥能力评价不一，晚年未再担任重要军职。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:42:49.534429','','扬州','高邮',null,null,null,null,'江苏江都','2','汪伪国民党中央执行委员、伪江苏省政府委员','0',null,null,null);
