INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('a5468b9bcdcbfb36233370a85d9b2001','博彦满都',null,null,'1894','1980','approx','approx','内蒙古哲里木盟科尔沁左翼前旗','["\\u535A\\u5F66\\u6EE1\\u90FD"]','["\\u8499\\u53E4\\u65CF\\u653F\\u6CBB\\u4EBA\\u7269","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u5185\\u8499\\u53E4\\u81EA\\u6CBB\\u8FD0\\u52A8\\u53C2\\u4E0E\\u8005"]','民国','蒙古自治运动、伪满洲国、内蒙古自治运动','博彦满都，蒙古族，内蒙古哲里木盟科尔沁左翼前旗人。早年参与蒙古族地方事务，1930年代在伪满洲国统治下出任兴安局官员，后升任兴安总署长官等职，成为伪满政权中蒙古族高层官员之一。1945年日本战败后，他转向内蒙古民族自治运动，参与筹备东蒙古人民自治政府，并任重要职务。1947年内蒙古自治区成立后，曾任内蒙古自治区人民政府参事室主任等职。其一生跨越清末、民国、伪满及新中国时期，身份复杂，既有在伪满政权中任职的经历，也在战后参与内蒙古自治运动，是近代内蒙古政治史中具有争议性的人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:59:58.038903','','呼伦贝尔','扎兰屯；牙克石',null,null,null,null,'内蒙古哲里木盟科尔沁左翼前旗','2','伪兴安南省省长','0',null,null,null);
