INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('a65d24467daad38764e6606aa23950e6','张岚峰','腾霄','子杰','1902','1952','exact','exact','河南省柘城县','["\\u5F20\\u5C9A\\u5CF0"]','["\\u4F2A\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权、伪军','张岚峰(1902-1952)，字腾霄，号子杰．柘城县林张村人，出生于破落地主家庭。兄弟3人，张岚峰从小过继其叔张映辰(系柘城县大恶霸，建国后被政府镇压)为子。幼年在家乡小学读书。民国6年(1917)，考入淮阳河南省立第四中学。民国10年(1921)春，投奔西北军，二年后升为连长。民国14年(1925)春，张奉冯玉祥命，留学日本陆军士官学校接受军事教育。三年后回国，任国民革命第二集团军第十三炮兵团团长。继而任西北军军官学校校长兼教育长。民国19年(1930)，蒋阎冯中原大战，冯玉祥兵败，张也失去军职。民国21年(1932)12月，张重到日本早稻田大学以研究经济为名再渡日本，与日本特务松室考良拉上关系，参加日本特务组织，至此走上卖国求荣的道路。民国27年(1938)5月，豫东沦陷后，张岚峰受日酋寺内寿一的指令，带着日本拨的30万元经费，在商丘设立华北派遣军总部豫东招抚使公署。在鹿邑、毫县、宁陵、睢县、柘城等地搜罗一批土匪、地主、失意军官、投机分子等1.8万人，编为“豫东剿共军”，张自称司令。民国28年(1939)4月，日军在开封组织绥靖委员会，以胡毓坤为主任，张岚峰等9人为委员，张的“豫东剿共军”改为“中央和平救国军第一军”。日军拨给大批军用物资。汪伪南京政府成立后，张向汪通款，汪又委任张为苏豫边区绥靖副司令兼第一军军长，军事委员会委员。后任第四方面军司令，共辖3个军，10个师，号称10万人马。张效忠日军，策动国民党第39集团军副总司令、兼冀察战区副总司令孙良诚率部投日本，并迎孙到商丘发表”和平通告”。张在商丘城内设立情报队，搜集抗日军队的各种情报提供给日军。他亲自率部配合El军向抗日军队进攻，积极推行。强化治安”，组织剿共队，力图扑灭人民抗日烽火。走私贩毒，横征暴敛，为日军。以战养战”的侵华提供物资。暗与蒋介石勾结，达成联合反共的默契。民国32年(1943)到民国33年(1944)，张岚峰对其辖区进行3次“强化治安”，组织警备队，维护东自砀山，西至开封这段铁路畅通，使日军调运兵力、物资向新四军进攻。民国33年(1944)秋到民国34年(1945)秋，中共中央平原局派卢渭，冀鲁豫军区党委派李苏波、苗泽生等两次向张晓以民族大义，宣传抗日救国主张，以及对张部官兵政策。第三次李苏波携带朱总司令给张的亲笔信，劝其弃暗投明。张却一面与新四军周旋，一面利用各种渠道，积极向蒋介石靠拢，并正式接受蒋介石“豫皖先遣军总司令”的委任状，决心与人民为敌。民国35年(1946)2月16日，蒋介石在南京召见张，令其反共。4月，又让张参加高级将领会议，并与之合影。张受宠若惊，决心。肝脑涂地，效忠党国”。同时，张配合国民党六十八军对水东解放区进行“清剿”，先后与共产党武装激战30余次。共产党武装避其锐转战杞县、通许。张复对两县人民进行惨无人道的大屠杀。12月下旬，晋冀鲁豫野战军连克钜野、嘉祥，围攻驻金乡之敌方先觉部。张奉命率两个团由民权出发，配合国民党十六军救援金乡。民国36年(1947)元月，行至大杨集，被人民解放军截击包围。张负隅顽抗，一昼夜激战，张岚锋仅率少数随从落荒而逃。1947年2月，在单县西南韦洼村附近被俘。1952年，病死于北京功德林。','[]','2026-09-12 13:06:46.288172','2026-09-16 08:38:53.655153','','','',null,null,null,null,'河南省柘城县','2','伪第四方面军总司令','0',null,null,null);
