INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('a6c97f95b84ad96cebc5c3377e6aa3d0','张之洞','孝达','香涛','1837','1909','exact','exact','直隶南皮','["\\u5F20\\u9999\\u6D9B","\\u5F20\\u9999\\u5CA9","\\u62B1\\u51B0","\\u65E0\\u7ADE\\u5C45\\u58EB","\\u5F20\\u5357\\u76AE"]','["\\u665A\\u6E05\\u91CD\\u81E3","\\u6D0B\\u52A1\\u6D3E\\u4EE3\\u8868","\\u6559\\u80B2\\u5BB6","\\u5B66\\u8005"]','清末','清廷洋务派','张之洞（1837—1909），字孝达，号香涛，直隶南皮人，生于贵州兴义府。同治二年进士，历官翰林院编修、山西巡抚、两广总督、湖广总督、两江总督，官至体仁阁大学士、军机大臣。中法战争期间筹饷调兵，支持冯子材取得镇南关大捷。督粤时创办广雅书院、广东水陆师学堂；督湖广近二十年，兴办汉阳铁厂、湖北枪炮厂、湖北织布局，修筑芦汉铁路，设两湖书院、自强学堂，编练新军，使湖北成为洋务重镇。戊戌变法期间著《劝学篇》，倡“中体西用”，既主张学习西方技艺，又维护纲常名教。庚子事变参与东南互保，稳定长江流域。晚年入枢垣，督办粤汉、川汉铁路。其《书目答问》《輶轩语》影响士林。清廷谥文襄。张之洞是晚清自强运动后期核心人物，其洋务实践与教育革新对中国近代化有重要推动，但政治立场保守，反对民权，亦为后世所议。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:13:18.071324','','武汉；西安','江岸；蓝田',null,null,null,null,'贵州兴义府','2','伪山西省长','0',null,null,null);
