INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('aa21737997120e994146f03626159738','王揖唐','慎吾','揖唐','1877','1948','exact','exact','安徽合肥','["\\u738B\\u8D53","\\u9038\\u5858","\\u4E00\\u5802"]','["\\u5B89\\u798F\\u7CFB\\u9996\\u9886","\\u5317\\u6D0B\\u653F\\u5BA2","\\u6C6A\\u4F2A\\u6C49\\u5978","\\u4F2A\\u8003\\u8BD5\\u9662\\u957F"]','民国','皖系、安福系、汪伪政权','王揖唐，字慎吾，号揖唐，安徽合肥人。清末进士，留学日本，入北洋幕府，为皖系干将。1918年组织安福俱乐部，操纵国会，史称“安福系”。历任北洋政府内务总长、众议院议长等职。抗战爆发后投敌，1937年参与组织伪中华民国临时政府，任内政部长。1940年汪伪国民政府成立后，任考试院长、华北政务委员会委员长等伪职，推行奴化教育，协助日军掠夺物资，镇压抗日活动。1945年抗战胜利后被捕，1948年以汉奸罪处决。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:27:24.793658','','合肥；蚌埠；高；宜春；郑州','息烽；婺源；蚌埠高；西；奉新；中牟',null,null,null,null,'安徽合肥','1','伪华北政务委员会委员长','0',null,null,null);
