INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ad578aa6b54fdcf2200b1160196476d7','溥仪',null,null,'1906','1967','exact','exact','北京','["\\u7231\\u65B0\\u89C9\\u7F57\\u00B7\\u6EA5\\u4EEA","\\u5BA3\\u7EDF\\u5E1D","\\u6E05\\u900A\\u5E1D","\\u5EB7\\u5FB7\\u7687\\u5E1D"]','["\\u6E05\\u671D\\u672B\\u4EE3\\u7687\\u5E1D","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u7687\\u5E1D","\\u6218\\u72AF","\\u5168\\u56FD\\u653F\\u534F\\u59D4\\u5458"]','民国','清朝皇室、伪满洲国','爱新觉罗·溥仪，清朝末代皇帝，光绪帝之侄、醇亲王载沣之子。1908年入宫即位，年号宣统。1912年中华民国成立后被迫退位，清朝灭亡。此后仍居紫禁城，1924年冯玉祥发动北京政变后被逐出宫。1931年九一八事变后，在日本关东军策动下潜往东北，1932年出任伪满洲国执政，1934年称帝，改元康德，成为日本侵华傀儡政权的象征。1945年日本战败后被苏联红军俘获，1950年移交中国，在抚顺战犯管理所接受改造。1959年获特赦，后任全国政协委员、中央文史研究馆馆员。1967年病逝于北京。其一生由皇帝到公民的转变，是近代中国剧烈变迁的缩影，其投敌卖国行为亦为历史所铭记。','[]','2026-09-12 13:06:46.288172','2026-09-15 02:30:30.548822','','桂林；沙坪坝','七星',null,null,null,null,'北京什刹海醇亲王府','1','伪满洲国执政、皇帝','0',null,null,null);
