INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('b16369af47e3f8a7e5e137d32c25bb1a','苑福堂',null,null,null,null,'exact','exact','饶河大别拉坑、暴马顶子','[]','["饶河伪地方特务头目"]','抗日战争时期','','伪职：饶河伪地方特务头目；罪行：组建汉奸走狗队，抓捕饶河县委、反日会成员，逮捕李学福等 20 多名抗日骨干，破坏饶河地下党组织中国军网。；结局：抗战胜利后反奸清算被公审镇压。','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','黑龙江','双鸭山','',null,null,null,null,'','5','饶河伪地方特务头目','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('b16bb28d1caf596d39ff5d597ce26dc9','刘文辉','自乾',null,'1895','1976','exact','exact','四川大邑','["\\u5218\\u81EA\\u4E7E","\\u897F\\u5EB7\\u738B"]','["\\u5DDD\\u519B\\u5C06\\u9886","\\u897F\\u5EB7\\u7701\\u4E3B\\u5E2D","\\u8D77\\u4E49\\u5C06\\u9886","\\u6C11\\u9769\\u4E2D\\u592E\\u5E38\\u59D4"]','民国','川军、国民革命军、西康省政府、中国国民党革命委员会','刘文辉，字自乾，四川大邑人，川军将领刘湘之堂侄。早年入四川陆军小学、保定陆军军官学校，毕业后在川军刘存厚、刘湘部历任要职，参与四川军阀混战。1920年代起割据川南、西康一带，1928年任四川省政府主席，1930年代与刘湘争夺四川霸权失败后退守西康。1939年西康建省，任西康省政府主席，主政十余年，有“西康王”之称。抗日战争时期，曾参与后方建设与康藏事务。1949年12月与邓锡侯、潘文华等在四川彭县通电起义，投向中国共产党。中华人民共和国成立后，历任西南军政委员会副主席、四川省政协副主席、林业部部长、国防委员会委员、全国人大常委会委员、民革中央常委等职。1976年6月24日在北京病逝。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:55:28.555337','','成都；巫溪；江津；涪陵；宝鸡','彭州；邛崃；凤县',null,null,null,null,'四川大邑安仁镇','2','伪西康省政府主席','0',null,null,null);
