INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('b22c75352e65544c60a1085d9ca94f44','蔡运升','品三',null,'1875','1959','approx','exact','吉林双城','["\\u8521\\u54C1\\u4E09"]','["\\u4F2A\\u6EE1\\u5B98\\u5458","\\u6C49\\u5978","\\u5916\\u4EA4\\u5B98"]','民国','奉系、伪满洲国','蔡运升，字品三，吉林双城人，清末附生。早年投效奉系，历任黑龙江都督府参谋、吉林滨江道尹兼哈尔滨交涉员等职。1929年中东路事件中，他代表东北当局与苏联签订《伯力协定》，因此被南京国民政府免职。九一八事变后，蔡运升投靠日本，参与策划成立伪满洲国，任伪满财政部次长、吉林省长等要职。1934年后任伪满驻日大使、外交部大臣，积极推行亲日外交，为日本侵略政策服务。1945年伪满覆灭后，蔡运升被苏联红军逮捕，押往西伯利亚，1950年被引渡回中国，关押于抚顺战犯管理所。1959年病逝于抚顺。其一生由奉系官僚堕落为汉奸，是民国时期东北地方实力派投敌的典型人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:59:58.810212','','白山','',null,null,null,null,'吉林双城','2','伪满经济部大臣、伪满吉林省长','0',null,null,null);
