INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('b61c4f95cf806cd4677ee97b73c920b7','张啸林','啸林',null,'1877','1940','exact','exact','浙江慈溪','["\\u5F20\\u5C0F\\u6797","\\u5F20\\u5BC5"]','["\\u9752\\u5E2E\\u5934\\u76EE","\\u6C49\\u5978","\\u4E0A\\u6D77\\u4E09\\u5927\\u4EA8"]','民国','青帮','张啸林，原名张小林，浙江慈溪人，上海青帮头目，与黄金荣、杜月笙并称上海三大亨。早年混迹上海滩，加入青帮，靠赌博、鸦片等非法生意起家，后投靠军阀势力，成为上海地方一霸。1927年四一二政变中，张啸林参与镇压工人纠察队，支持蒋介石清党。抗日战争爆发后，上海沦陷，张啸林公开投敌，组织伪“新亚和平促进会”，为日军筹办军需物资，并策划出任伪浙江省主席，沦为汉奸。1940年8月14日，张啸林被其贴身保镖林怀部刺杀于上海寓所，结束其罪恶一生。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:16:49.925834','','杨浦；金山；宁波；玉林；九江；杭州；温州；咸宁','慈溪；兴业；濂溪；余姚；上城；桐庐；西湖；瑞安；瓯海；德清；通山',null,null,null,null,'浙江慈溪','1','伪上海特别市维持会会长','0',null,null,null);
