INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ba7c2afb8d9eca406f9893384099438f','赵尊岳','叔雍','珍重阁','1898','1965','exact','exact','江苏武进','["\\u8D75\\u53D4\\u96CD","\\u73CD\\u91CD\\u9601\\u4E3B"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u8BCD\\u5B66\\u5BB6","\\u62A5\\u4EBA"]','民国','汪伪政权','赵尊岳（1898—1965），字叔雍，号珍重阁，江苏武进人。早年师从词学大家况周颐，深研词学，为民国时期著名词学家、报人。曾任职于上海《时报》，后任《申报》馆秘书、主笔，并执教于上海多所高校。抗日战争期间，赵尊岳投靠汪精卫伪政权，历任汪伪国民党中央委员、伪宣传部次长、伪行政院参事等职，为汪伪政权文化宣传要员。抗战胜利后，以汉奸罪被国民政府逮捕，判处有期徒刑。1949年后寓居香港，继续词学研究，1965年病逝。其一生词学著作宏富，编有《明词汇刊》、《珍重阁词话》等，对词学文献整理贡献颇大，但因附逆汪伪，历史评价颇具争议。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:57:53.484066','','安庆；芜湖；南京；常州','芜湖经开区；镜湖；鼓楼；武进',null,null,null,null,'江苏武进','2','伪华北政务委员会教育总署督办','0',null,null,null);
