INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('bb20f607d70cdb4f02e97c00e48fc034','刘建绪','恢先',null,'1892','1978','exact','exact','湖南醴陵','["\\u5218\\u6062\\u5148"]','["\\u56FD\\u6C11\\u515A\\u5C06\\u9886","\\u6E58\\u519B\\u5C06\\u9886","\\u798F\\u5EFA\\u7701\\u4E3B\\u5E2D"]','民国','国民党湘军','刘建绪，字恢先，湖南醴陵人，民国时期国民党湘军重要将领。早年入保定陆军军官学校第三期，毕业后回湘军任职，长期追随唐生智、何键。1926年参加北伐，任第八军团长、旅长。1929年后在何键麾下任第十九师师长、第二十八军军长等职，参与对中央苏区的“围剿”。1935年任第四路军总指挥，率部追堵长征红军。抗日战争爆发后，任第十集团军总司令，参加淞沪会战，后任第三战区副司令长官，兼第二十三集团军总司令，在浙赣皖边坚持抗战。1941年任福建省政府主席，主闽七年。1948年任战略顾问委员会委员。1949年赴香港，与李宗仁等联名通电起义，后移居巴西，1978年在巴西病逝。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:46:46.510587','','杨浦；桂林；南京；九江；南昌；吉安；新余；萍乡；赣州；怀化；株洲；永州；湘潭；衡阳；邵阳','恭城；浦口；武宁；新建；青山湖；井冈山；吉州；永丰；永新；青原；分宜；上栗；上犹；瑞金；溆浦；天元；醴陵；双牌；道县；湘乡；衡南；北塔；城步；大祥；新宁；武冈；洞口；邵东；隆回',null,null,null,null,'湖南醴陵','2','伪上海特别市沪东区煤气公司经理','0',null,null,null);
