INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('bc87ff13b1d2d562b63d31e83986908c','吴望伋',null,null,null,null,'unknown','unknown','浙江金华','[]','["\\u4F2A\\u5546\\u4F1A\\u4F1A\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','抗日战争时期','汪伪政权','吴望伋，浙江金华人，生卒年不详。抗日战争时期，金华沦陷后，吴望伋投靠日伪，出任伪金华商会会长，成为汪伪政权在金华地区的重要附逆人物。任伪职期间，他协助日军维持殖民统治，为日军筹款筹粮、摊派物资，并参与经济统制，配合日军掠夺金华地区资源，对当地民众进行压榨。其具体罪行包括为日军征用物资、强制商户纳捐、协助日军封锁物资等，严重危害了金华地区的抗日力量与民众生计。抗战胜利后，吴望伋作为汉奸受到国民政府惩处，但其具体审判结果及晚年情况因史料匮乏而难以详考。其生平事迹主要见于金华地方文史资料及抗战时期汉奸惩处档案，是研究沦陷区伪政权基层附逆人物的典型案例。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:59:29.155388','','金华','',null,null,null,null,'','2','伪金华商会会长','0',null,null,null);
