INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('bd90aa6205d4e2ab5cf6b91d203ad7e2','杨为桢',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u5B98\\u5458","\\u6559\\u80B2\\u754C\\u4EBA\\u58EB"]','民国','汪伪政权','杨为桢，生平事迹待考。据现有资料，其曾在汪伪南京国民政府中任职，被指为伪教育部长，属抗战时期投靠日本、参与伪政权的附逆人员。汪伪政权于1940年3月在南京成立，名义上以“还都”为号召，实为日本侵略者扶植的傀儡政权，其教育行政机构负责推行奴化教育、控制沦陷区学校与师生思想。杨为桢若确任伪教育部长，则其任内当参与制定与执行亲日教育政策，为日军文化侵略服务。然因史料匮乏，其具体籍贯、生卒年月、任职起讫及个人经历均难以确证，尚待进一步查考档案与报刊资料。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:20:16.990179','','','',null,null,null,null,'','7','伪南京国民政府教育部长','0',null,null,null);
