INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('bfafa6d050c28fff7a0f6ccf76e00eee','何世桢',null,null,'1894','1972','approx','approx','安徽望江','["\\u4F55\\u601D\\u6BC5"]','["\\u56FD\\u6C11\\u515A\\u5143\\u8001","\\u6C6A\\u4F2A\\u7ACB\\u6CD5\\u9662\\u526F\\u9662\\u957F","\\u519B\\u7EDF\\u6F5C\\u4F0F\\u4EBA\\u5458"]','民国','中国国民党（西山会议派）、汪伪政权（表面附逆，实为潜伏）','何世桢，安徽望江人，早年留学美国，获哥伦比亚大学法学博士。回国后任东吴大学法学院教授、上海公共租界临时法院推事，后投身国民党，为西山会议派成员。抗日战争爆发后，何世桢受军统局长戴笠派遣，利用与汪伪政权要员的旧交，潜入汪伪政府，先后担任汪伪国民党中央执行委员、立法院副院长、司法院院长等伪职，表面为日伪效力，实则向重庆方面提供大量情报，并掩护军统地下活动。抗战胜利后，其潜伏身份未获公开承认，一度被国民政府以汉奸罪逮捕，后经戴笠等人证明获释。1949年后留居上海，1972年在上海病逝。其一生功过交织，既是国民党元老，又是抗战时期隐蔽战线的重要人物，历史评价复杂。','[]','2026-09-12 13:06:46.288172','2026-09-14 04:19:41.962177','','合肥；南京','庐江；浦口；鼓楼',null,null,null,null,'安徽望江','2','伪安徽省高等法院院长','0',null,null,null);
