INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('c0828c6720723340d7e468dec7d708c3','王克镇',null,null,null,null,'unknown','unknown','','[]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u4F2A\\u6EE1\\u5B98\\u5458","\\u6295\\u65E5\\u5C06\\u9886"]','民国','东北军；伪满洲国','王克镇，生卒年与籍贯不详，民国时期东北军军官。九一八事变前，任黑龙江省防军骑兵第二旅少将旅长，隶属东北军系统，驻防黑龙江。1931年九一八事变后，日军进犯黑龙江，马占山一度率部抵抗。1932年马占山一度妥协就任伪黑龙江省长前后，王克镇随部分东北军将领投附日军，所部被编入伪满军警系统，成为日本侵略者控制黑龙江地区的工具。其投敌行为削弱了东北抗日武装力量，为日军迅速占领和稳定黑龙江局势提供了助力。此后其具体任职与结局史料记载零散，难以确考。','[]','2026-09-12 13:06:46.288172','2026-09-15 06:24:17.494545','','伊春；大庆','丰林；杜尔伯特',null,null,null,null,'','3','伪满伊春地区伪警察署长','0',null,null,null);
