INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('c29a1d9d6f03d19fd471ab1b9879a8af','王永江','岷源','铁龛','1871','1927','exact','exact','山东蓬莱','[]','["\\u5949\\u7CFB\\u5B98\\u5458","\\u8D22\\u653F\\u5BB6","\\u6559\\u80B2\\u5BB6"]','民国','奉系','王永江（1871—1927），字岷源，号铁龛，山东蓬莱人，生于奉天金州。清末以岁贡生出身，曾任辽阳警务学堂监督、奉天省警务局参事等职。民国后投效奉系张作霖，历任奉天省财政厅厅长、东三省官银号督办、奉天省省长等要职。主政奉天期间，大力整顿财政，改革税制，使奉天省库扭亏为盈；同时创办东北大学，自任首任校长，推动东北近代教育发展。他主张保境安民、发展实业，反对张作霖穷兵黩武、入关争霸，因与张作霖及杨宇霆等意见相左，于1926年愤而辞职，退居金州故里。1927年病逝，享年56岁。王永江为奉系集团中少有的理财干才与文治派代表，其治理奉天的政绩为时人所称道，然其保守立场亦限制其政治作为。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:47:55.833151','','松原；舒兰；长春；太原；承德；秦皇岛；大连；朝阳；沈阳；盘锦；葫芦岛；辽阳；铁岭；锦州；阜新；鞍山；佳木斯；哈尔滨；绥化','松原经开区；朝阳；清徐；双滦；隆化；鹰手营子矿；山海关；瓦房店；西岗；金州；长海；双塔；盘山；绥中；宏伟；白塔；开原；北镇；彰武；海州；铁东；同江；富锦；北林',null,null,null,null,'奉天金州（今辽宁大连金州区）','2','伪满四平省省长','0',null,null,null);
