INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('c6d02e412d5993ba839e7eb519bad205','臧式毅','奉久',null,'1885','1956','approx','exact','奉天省沈阳县','["\\u81E7\\u5949\\u4E45"]','["\\u5949\\u7CFB\\u5C06\\u9886","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u4F2A\\u5949\\u5929\\u7701\\u957F","\\u4F2A\\u53C2\\u8BAE\\u5E9C\\u8BAE\\u957F"]','民国','奉系、伪满洲国','臧式毅，字奉久，奉天沈阳人，清末赴日本陆军士官学校留学，归国后入奉系军界，历任东北陆军整理处参谋长、东三省保安总司令部参谋长等职，为张作霖、张学良父子所倚重。九一八事变后，日军占领沈阳，臧式毅未能及时撤离，被日本关东军扣押，随后变节投敌，出任伪奉天省省长，成为伪满洲国重要汉奸之一。其后历任伪满洲国参议府议长、伪民政部总长等要职，长期为日本殖民统治效力，参与推行奴化政策与资源掠夺。抗战胜利后，臧式毅被苏联红军逮捕，后移交中国，1956年病死于抚顺战犯管理所。其一生由奉系军政要员沦为伪满汉奸，是近代东北沦陷史中具有代表性的变节人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:33:54.548928','','四平；延边；松原；长春；沈阳；聊城；承德；朝阳；阜新；阳泉；双鸭山；大庆；牡丹江；绥化','梨树；延吉；前郭尔罗斯；松原经开区；农安；南关；双阳；宽城；德惠；长春汽车经开区；茌平；滦平；双塔；彰武；矿区；集贤；庆安；牡丹江经开区；明水',null,null,null,null,'奉天省沈阳县','1','伪满奉天省省长、伪满参议府议长','0',null,null,null);
