INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ce718da85ee93340a785b50f27b08ddb','薛兴甫',null,null,null,null,'exact','exact','河北石家庄石家庄高；河北石家庄高邑；河北石家庄高邑；冀南道（辖濮阳）；河北','[]','["伪高邑县知事", "伪高邑县教育科长", "伪冀南道尹", "伪邯郸县知事、伪高邑县教育科长、伪高邑县知事、石家庄伪市长（石门市）", "伪冀南道道尹（前期），冀南道最高伪行政长官；统辖 14 县伪政权，推行治安强化运动，组织各县伪军扫荡冀南根据地，掠夺粮棉物资。"]','抗日战争时期','','伪职：伪高邑县知事；伪职：伪高邑县教育科长；伪职：伪冀南道尹；罪行：河北籍，日伪高级文官，投降日军后任伪冀南道尹，管辖冀南、豫北十余县伪政权。统筹各县横征暴敛，指挥各县伪政权配合日军扫荡冀鲁豫根据地。1944年亲自到清丰县城召集13县伪县长开会；结局：1944年清丰战役中被八路军生擒，公审镇压；伪职：伪邯郸县知事、伪高邑县教育科长、伪高邑县知事、石家庄伪市长（石门市）；在高邑县为日军强征军粮，建立伪警察所，多次带队突袭抗日村庄，杀害无辜百姓。；强制学校使用日伪教材，推行奴化教育，解散抗日小学，迫害爱国教师，组织学生为日军“祝捷”活动。；任伪石门市市长，协助日军建立殖民统治，推行奴化教育，强征劳工，为日军提供后勤支持。；任伪邯郸县知事期间，为日军提供情报，组织伪警察抓捕抗日干部，参与‘治安强化运动’。；伪职：伪冀南道道尹（前期），冀南道最高伪行政长官；统辖 14 县伪政权，推行治安强化运动，组织各县伪军扫荡冀南根据地，掠夺粮棉物资。；结局：1944 清丰战斗被俘，公审枪决','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','河北','石家庄','石家庄高；高邑',null,null,null,null,'','3','伪高邑县知事','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ce75e44a697a931c1b4d71820fa9b55e','郑孝胥','苏戡','海藏','1860','1938','exact','exact','福建闽县','["\\u90D1\\u82CF\\u9F9B","\\u6D77\\u85CF\\u697C\\u4E3B\\u4EBA","\\u592A\\u5937"]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u603B\\u7406","\\u6C49\\u5978","\\u8BD7\\u4EBA","\\u4E66\\u6CD5\\u5BB6"]','民国','清末遗老、伪满洲国','郑孝胥，字苏戡，号海藏，福建闽县人，生于苏州胥门。清光绪八年举人，历任广西边防大臣、安徽广东按察使、湖南布政使等职。辛亥革命后以遗老自居，寓居上海，鬻书卖字，组织读经会，参与复辟清室活动。1923年经陈宝琛引荐入紫禁城，任懋勤殿行走，成为溥仪重要谋臣。1924年北京政变后协助溥仪出宫，后随其潜往天津日租界。九一八事变后，力主溥仪投靠日本，1932年伪满洲国成立，出任国务总理兼军政部总长、文教部总长，与日本签订《日满议定书》，出卖东北主权。1935年因主张国际共管被日方排挤去职。1938年病死于长春。其书法宗魏碑，诗宗宋人，有《海藏楼诗集》传世，但晚年附逆，大节有亏，为世所讥。','[]','2026-09-12 13:06:46.288172','2026-09-14 04:07:58.729757','','昆明；四平；长春；福州','呈贡；农安；德惠；绿园；长春高',null,null,null,null,'江苏苏州胥门','1','伪满洲国国务总理大臣','0',null,null,null);
