INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('cfcefe0d776b4d88829bfb6cb836b2e8','许兰洲','芝田',null,'1872','1951','approx','approx','直隶省南宫县','["\\u8BB8\\u829D\\u7530"]','["\\u5949\\u519B\\u5C06\\u9886","\\u9ED1\\u9F99\\u6C5F\\u7701\\u7763\\u519B","\\u4E1C\\u5317\\u519B\\u5C06\\u9886"]','民国','奉系','许兰洲，字芝田，直隶南宫人，清末投效军旅，隶北洋新军，累迁至协统。民国成立后依附张作霖，为奉系早期重要将领。1914年前后任黑龙江省陆军师长，1916年升任黑龙江督军兼省长，主政期间整饬军备、扩充奉系在江省势力，然与地方士绅及吉林方面多有龃龉。1917年因内部权力倾轧去职，转任奉军高级幕僚与军事参议。此后长期追随张作霖、张学良父子，参与奉军整编、军事教育及后方事务，九一八事变后未附逆，保持民族气节，晚年寓居平津，生活低调。其一生由清末旧军人转为奉系军政要员，是研究奉系军阀在黑龙江统治及东北军政格局演变的重要个案。','[]','2026-09-15 06:43:40.586161','2026-09-15 06:43:52.788511','',null,null,null,null,null,null,'直隶省南宫县',null,null,'0',null,null,null);
