INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('cfe03831b2026e0dc711012daee4a1cf','郝鹏举',null,null,'1903','1947','approx','exact','河南阌乡（今河南灵宝）','["\\u90DD\\u9E4F\\u4E3E\\uFF08\\u672C\\u540D\\uFF09","\\u90DD\\u9E4F\\u4E3E\\uFF08\\u5E38\\u7528\\u540D\\uFF09","\\u90DD\\u9E4F\\u4E3E","\\u90DD\\u9E4F\\u4E3E","\\u90DD\\u9E4F\\u4E3E"]','["\\u4F2A\\u6DEE\\u6D77\\u7701\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978","\\u53CD\\u590D\\u53DB\\u5C06","\\u4F2A\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u53CD\\u590D\\u53DB\\u53D8\\u8005","\\u4F2A\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u53DB\\u5C06","\\u4F2A\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u53CD\\u590D\\u53DB\\u53D8\\u8005"]','民国','西北军、汪伪、国民党、中共（反复叛投）','郝鹏举，河南阌乡人，早年投冯玉祥西北军，后随部附蒋。抗日战争时期投靠汪精卫伪政权，任伪淮海省省长兼伪保安司令，在苏北、淮海地区推行伪化统治，配合日军“清乡”“扫荡”，搜刮民财、残害抗日军民，是汪伪政权在淮海地区的重要汉奸头目。抗战胜利后，郝鹏举所部被国民党收编，任新编第六路军总司令。1946年1月，在中共争取下于台儿庄率部起义，所部改编为华中民主联军，郝任总司令。1947年1月，国民党军大举进攻山东解放区，郝鹏举再次叛变，率部投靠国民党，被委任为鲁南绥靖区司令官兼第四十二集团军总司令。同年2月，华东野战军发起白塔埠战役，将其部全歼，郝鹏举被俘。1947年4月，郝鹏举在押解途中被处决。其一生反复无常，投敌卖国，最终身败名裂。','[]','2026-09-12 13:06:46.288172','2026-09-14 08:35:55.566174','','晋中','左权',null,null,null,null,'河南阌乡（今河南灵宝）','2','伪淮海省省长','0',null,null,null);
