INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('d13f3429d51c4179a9dd78bf32cc0e0d','爱新觉罗·吉兴',null,null,'1886',null,'approx','unknown','奉天省沈阳县','["\\u5409\\u5174"]','["\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u4F2A\\u519B\\u5C06\\u9886","\\u6E05\\u671D\\u5B97\\u5BA4"]','民国','奉系军阀、伪满洲国','爱新觉罗·吉兴，清朝宗室后裔，奉天省沈阳县人。早年投身军旅，毕业于日本陆军士官学校，回国后长期在奉系军阀张作霖、张学良麾下任职，历任东北军团长、旅长等职。九一八事变后，吉兴投靠日本侵略者，参与策划成立伪满洲国，出任伪满洲国军政部要职，后任伪满洲国军上将、伪热河省省长等职，积极协助日本关东军镇压东北抗日武装、推行殖民统治，是伪满洲国政权中重要的汉奸军事人物之一。1945年日本战败后，吉兴被苏联红军逮捕，后移交中国，作为战犯被关押审判。其具体生卒年及晚年结局史料记载不一，有待进一步考证。','[]','2026-09-15 06:08:08.534366','2026-09-15 06:08:43.869397','',null,null,null,null,null,null,'奉天省沈阳县',null,null,'0',null,null,null);
