INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('da264b8635ba4a078c13fb08bcbddb21','缪澄流','开源',null,'1901','1990','approx','approx','辽宁清原','["\\u7F2A\\u5F00\\u6E90"]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u56FD\\u6C11\\u515A\\u9646\\u519B\\u4E2D\\u5C06","\\u6297\\u65E5\\u5C06\\u9886"]','民国','东北军','缪澄流，字开源，辽宁清原人，满族。早年投身奉军，为张学良所部东北军重要将领。历任东北军连长、营长、团长、旅长等职。1931年九一八事变后，随东北军入关。1935年任东北军第一一五师师长。1936年西安事变时，率部驻防西安附近，支持张学良、杨虎城的抗日主张。抗日战争全面爆发后，率第一一五师参加淞沪会战、徐州会战等战役，在江苏、山东等地与日军作战。1938年后任第五十七军军长，隶属第五战区，参加武汉会战外围作战。东北军57军中将军长，与徐州日军鹫津师团签订“互不侵犯，共同防共”的秘密协定。事败后双双被解职，57军番号被取消。1940年后调任军事委员会高级参谋等职。1945年抗战胜利后退役。1949年赴台湾，1990年前后在台湾去世。','[]','2026-09-15 05:53:32.296035','2026-09-15 05:55:09.222579','',null,null,null,null,null,null,'辽宁省清原县',null,null,'0',null,null,null);
