INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('db8e72e80fa3a490dcb364ed24ce9026','林柏生',null,null,'1902','1946','exact','exact','广东信宜','["\\u6797\\u77F3\\u6CC9"]','["\\u6C6A\\u4F2A\\u5BA3\\u4F20\\u90E8\\u957F","\\u6C6A\\u4F2A\\u884C\\u653F\\u9662\\u5BA3\\u4F20\\u90E8\\u957F","\\u6C49\\u5978"]','民国','汪伪政权','林柏生，广东信宜人，早年就读于广州岭南大学，后赴莫斯科中山大学留学，与汪精卫集团关系密切。回国后长期从事国民党宣传工作，曾任《中华日报》社长等职，为汪精卫派系重要宣传骨干。抗日战争爆发后，1938年随汪精卫叛国投敌，参与筹建汪伪政权。1940年汪伪国民政府成立后，历任伪宣传部部长、伪行政院宣传部长、伪最高国防会议委员等要职，控制汪伪宣传机器，鼓吹“和平反共建国”谬论，为日本侵略者推行奴化宣传、粉饰侵略战争，是汪伪政权核心人物之一。1945年抗战胜利后被捕，1946年以汉奸罪被判处死刑，在南京执行枪决。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:23:17.150252','','茂名；宿州；汕尾；玉林；普洱；桂林；贵阳；杭州；温州；蚌埠','信宜；灵璧；陆河；陆川；西；恭城；淳安；瑞安',null,null,null,null,'广东信宜','1','汪伪宣传部部长','0',null,null,null);
