INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('dbb27188526adfeb89d6e4224ee69f51','李本一',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u8B66\\u5907\\u961F\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','抗日战争时期','汪伪政权','李本一，生卒年与籍贯不详，抗日战争时期任伪宿县（含相山）警备队长，属汪伪政权地方武装头目。宿县地处津浦铁路要冲，为日军控制皖北、屏障徐州之战略据点。李本一率伪警备队协同日军守备队维持“治安”，参与清乡、扫荡，搜捕抗日人员，征发民夫物资，为日军侵略服务。其队伍多由地方游杂武装与投敌分子编成，装备低劣，主要承担据点守备、修筑工事、配合日军行动等任务。抗战胜利后，此类伪职人员的具体下落与结局多不见于正史记载，李本一亦无可靠史料可考其终局。其名仅见于汪伪政权地方警备组织相关档案与地方志零星记录，生平事迹极为简略，属沦陷区附敌基层人员之一。','[]','2026-09-12 13:06:46.288172','2026-09-15 07:56:54.161932','','淮北','相山',null,null,null,null,'','6','伪宿县（含相山）警备队长','0',null,null,null);
