INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('dd5710414582d1832e433f47605d7560','董康','授经','诵芬室主人','1867','1947','exact','exact','江苏武进','["\\u8463\\u7EF6\\u7ECF","\\u8463\\u6388\\u7ECF"]','["\\u6CD5\\u5B66\\u5BB6","\\u85CF\\u4E66\\u5BB6","\\u4F2A\\u5B98\\u5458","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','汪伪政权','董康（1867—1947），字授经，号诵芬室主人，江苏武进人。清末进士，曾任刑部主事、大理院推事，后赴日本考察司法，入民国后历任大理院院长、司法总长、财政总长等职，为近代著名法学家、藏书家，主持编纂《续修四库全书总目提要》。抗战期间投敌附逆，1937年参与伪中华民国临时政府，后任汪伪政府要职，1940年任汪伪国民政府委员、司法行政部部长等伪职，为虎作伥，推行日伪法令，镇压抗日力量。抗战胜利后被国民政府逮捕，1947年病死狱中。其学术贡献与政治失节并存，历史评价以晚节不保、附逆投敌为定论。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:36:37.078521','','廊坊；西安；常州','固安；蓝田',null,null,null,null,'江苏武进','1','伪华北政务委员会司法委员会委员长','0',null,null,null);
