INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e438eb65987bd101130058e06ca443a1','褚民谊','重行',null,'1884','1946','exact','exact','浙江吴兴','["\\u891A\\u6C11\\u8C0A"]','["\\u4F2A\\u5916\\u4EA4\\u90E8\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权','褚民谊（1884—1946），字重行，浙江吴兴人。早年留学日本、法国，获医学博士学位。1924年任广东大学教授，后任国民党中央执行委员、国民政府委员等职。1937年抗日战争爆发后，留居上海。1939年追随汪精卫叛国投敌，参与筹建汪伪政权，历任汪伪国民党中央执行委员会秘书长、伪外交部长、伪驻日大使、伪广东省长等要职，积极推行亲日卖国政策，协助日军掠夺物资、镇压抗日力量。1945年抗战胜利后被捕，1946年以汉奸罪被判处死刑，在南京执行枪决。其一生由学者从政，最终沦为民族罪人，为后世所唾弃。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:35:45.593898','','宣城；湛江；湖州；阳江；韶关；贵阳；苏州','吴兴；霞山；阳春；始兴；张家港',null,null,null,null,'浙江吴兴','1','汪伪外交部长、广东省长','0',null,null,null);
