INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e599bfca0c0edb35b0cdba2f1f50ecc7','刘峙','经扶','天岳','1892','1971','exact','exact','江西吉安','["\\u5218\\u7ECF\\u6276","\\u5218\\u5929\\u5CB3"]','["\\u56FD\\u6C11\\u515A\\u519B\\u9AD8\\u7EA7\\u5C06\\u9886","\\u6297\\u65E5\\u5C06\\u9886","\\u5F90\\u5DDE\\u527F\\u603B\\u603B\\u53F8\\u4EE4"]','民国','中国国民党','刘峙，字经扶，号天岳，江西吉安人，国民党军高级将领，二级陆军上将。早年入保定军校，后投粤军，1924年任黄埔军校教官，参与东征、北伐。中原大战中为蒋介石击败冯玉祥、阎锡山部立功，获“常胜将军”之名。抗战时期历任第一战区第二集团军总司令、第五战区司令长官等职，率部参加保定、娘子关、台儿庄等战役，但亦有指挥失误。解放战争时期任郑州绥靖公署主任、徐州剿总总司令，淮海战役中指挥国民党军主力被歼，战后被撤职查办。1949年后赴香港、印尼，1954年赴台湾，任总统府国策顾问等闲职。1971年病逝于台北。其一生由北伐名将沦为败军之将，军事评价两极。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:45:14.578090','','亳州','涡阳',null,null,null,null,'江西吉安','2','伪安徽省长','0',null,null,null);
