INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e5bfb340566a3dca9346d89881d0127a','傅筱庵','宗耀',null,'1872','1940','exact','exact','浙江镇海','["\\u5085\\u5B97\\u8000","\\u5085\\u5C0F\\u5EB5"]','["\\u4F2A\\u4E0A\\u6D77\\u5E02\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权','傅筱庵，字宗耀，浙江镇海人，清末民初实业家、银行家。早年在上海经商，曾任上海总商会会长、中国通商银行总经理等职，为沪上商界闻人。抗日战争爆发后，上海沦陷，傅筱庵于1938年投敌，出任伪上海特别市市长，沦为汉奸。任伪职期间，他协助日军维持殖民统治，镇压抗日活动，搜刮民财，为虎作伥，激起国人公愤。1940年10月，傅筱庵被军统策反的仆人朱升源刺杀身亡。其一生由商界领袖堕落为民族罪人，是抗战时期投敌附逆的典型人物之一。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:06:01.140320','','宁波；广州','镇海；白云',null,null,null,null,'浙江镇海','1','伪上海特别市市长','0',null,null,null);
