INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e87afab0f8aaa05b6193a8dd03066e83','陈曾栻',null,null,null,null,'unknown','unknown','','[]','["\\u4F2A\\u4FDD\\u5B9A\\u5E02\\u5E02\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u6CB3\\u5317\\u7701\\u8B66\\u5BDF\\u5385\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458"]','民国','汪伪政权','陈曾栻，生卒年与籍贯不详，民国时期人物。抗日战争进入相持阶段后，日军在华北占领区扶植伪政权，陈曾栻投靠日伪，出任伪河北省警察厅长，成为汪伪政权在河北地区维持殖民统治、镇压抗日力量的重要爪牙。任内秉承日军意旨，统辖伪警察队伍，配合日军进行治安强化运动，搜捕抗日人员与爱国群众，推行保甲连坐，强征民夫物资，对河北敌后抗日根据地和沦陷区民众造成严重危害。其具体生卒、早年经历及抗战胜利后的下落，因史料零散，尚难确考。','[]','2026-09-12 13:06:46.288172','2026-09-16 08:45:22.571868','','','',null,null,null,null,'','4','伪河北省警察厅长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e87ef10140db86940c054d8229fe5ded','赵玉昆',null,null,null,'1950','unknown','approx','河北易县','["\\u8D75\\u8001\\u7389"]','["\\u4F2A\\u519B\\u5934\\u76EE","\\u6C49\\u5978","\\u571F\\u532A"]','抗日战争时期','伪军/汉奸','赵玉昆，河北易县一带人，早年落草为寇，为当地土匪武装首领。抗日战争全面爆发后，曾一度与八路军合作，所部被改编为晋察冀军区部队，赵任分区司令员等职。1939年前后率部叛变投敌，投降日军，被编入伪军，任伪易县警备队及伪军要职，配合日军对晋察冀抗日根据地实行扫荡、清剿，捕杀抗日军民，烧毁村庄，掠夺物资，对当地抗日力量造成严重危害。抗战胜利后，赵玉昆继续与人民为敌，依附国民党势力。中华人民共和国成立后，于1950年前后被人民政府逮捕并依法处决。其一生由土匪而抗日、由抗日而投敌，最终沦为汉奸，是华北地区投敌叛国、为虎作伥的典型人物。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:02:15.695937','','赤峰；保定；廊坊；衡水；黑河；忻州','喀喇沁旗；松山；翁牛特旗；保定白沟新城；保定高；安新；徐水；易县；曲阳；望都；涞水；涞源；涿州；满城；竞秀；蠡县；雄县；文安；故城；北安',null,null,null,null,'河北易县','2','伪赤峰县警察署长','0',null,null,null);
