INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e8966f0c62324c0d1949bf3682ef8651','周良玉',null,null,null,null,'exact','exact','钟祥县','[]','["日伪鄂西保安军二团团长→新四军五师特三旅旅长（后叛变）"]','抗日战争时期','','伪职：日伪鄂西保安军二团团长→新四军五师特三旅旅长（后叛变）；罪行：钟祥柴湖人，土匪出身。当地沦陷后投靠日军。1943年2月率部投奔新四军五师，被编为特三旅任旅长。同年9月日军大扫荡时叛变投敌，绑架政工干部谢威、杜邦宪等人，将杜邦宪装入麻袋沉水杀害。被称为“钟祥抗战历史上最大的汉奸”；结局：后被自己的警卫员杀死','[]','2026-09-12 13:06:46.288172','2026-09-12 13:06:46.288172','','','',null,null,null,null,'','5','日伪鄂西保安军二团团长→新四军五师特三旅旅长','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('e89a4223c96ed4a5b94cb13150c4c0fd','樊仲云',null,null,'1901',null,'approx','unknown','浙江绍兴','["\\u6A0A\\u4EF2\\u4E91"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u6559\\u80B2\\u6B21\\u957F","\\u62A5\\u4EBA","\\u7FFB\\u8BD1\\u5BB6"]','民国','汪伪政权','樊仲云，浙江绍兴人，早年从事新闻与出版工作，曾任《东方杂志》编辑，并参与创办《新生命》月刊，为国民党改组派系外围的文化人之一。抗日战争爆发后留居上海，1939年汪精卫叛国投敌后，樊仲云追随汪伪集团，出任汪伪国民党中央宣传部副部长、伪国民政府教育部次长等要职，并主持伪《中华日报》笔政，为汪伪政权鼓吹“和平建国”谬论，进行亲日卖国宣传。其著述与译作颇多，包括《国际政治之理论与实际》《东西学者之中国革命论》等。抗战胜利后，樊仲云以汉奸罪被国民政府逮捕审判，其后事迹不详。作为文化人投敌附逆的典型，其生平反映了抗战时期部分知识分子在民族危亡之际丧失气节的历史教训。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:41:47.117549','','杨浦；广元；桂林；南京；九江；西安','恭城；江宁；浦口',null,null,null,null,'浙江绍兴','2','伪中央大学校长','0',null,null,null);
