INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ebb64ecd687a4373037d77126c16063b','齐默特色木丕勒',null,null,'1874','1942','approx','approx','内蒙古哲里木盟郭尔罗斯前旗','["\\u9F50\\u738B","\\u9F50\\u9ED8\\u7279","\\u9F50\\u9ED8\\u7279\\u8272\\u6728\\u4E15\\u52D2"]','["\\u8499\\u53E4\\u738B\\u516C","\\u4F2A\\u6EE1\\u6D32\\u56FD\\u5B98\\u5458","\\u4F2A\\u5174\\u5B89\\u5C40\\u603B\\u88C1"]','民国','蒙古王公、伪满洲国','齐默特色木丕勒，内蒙古哲里木盟郭尔罗斯前旗末代札萨克辅国公，人称“齐王”。清末袭爵，民国初年任郭尔罗斯前旗札萨克，后历任哲里木盟盟长、蒙古各盟旗联合驻京办事处处长等职。1931年九一八事变后，他投靠日本侵略者，参与策划蒙古“自治”活动。1932年伪满洲国成立，他出任伪兴安局总裁，后任伪兴安总署总长、伪蒙政部大臣等要职，成为日本殖民统治蒙古地区的代理人。他协助日本推行“蒙地奉上”政策，出卖蒙古土地权益，镇压抗日力量，对蒙古族人民犯下严重罪行。1942年前后病死于长春，其一生由清朝王公蜕变为伪满汉奸，是近代蒙古王公投敌卖国的典型代表。','[]','2026-09-12 13:06:46.288172','2026-09-15 08:53:34.025607','','兴安','突泉',null,null,null,null,'郭尔罗斯前旗','7','伪兴安局总裁、伪满洲国参议','0',null,null,null);
