INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ebf96f1cd9938c6c1c7a4c20a20167ca','张治中','文白',null,'1890','1969','exact','exact','安徽巢县（今安徽巢湖）','["\\u5F20\\u672C\\u5C27","\\u5F20\\u8B66\\u9B44"]','["\\u56FD\\u6C11\\u515A\\u9AD8\\u7EA7\\u5C06\\u9886","\\u548C\\u5E73\\u5C06\\u519B","\\u9EC4\\u57D4\\u7CFB\\u9AA8\\u5E72","\\u65B0\\u4E2D\\u56FD\\u9886\\u5BFC\\u4EBA"]','民国','国民党（和平将军）','张治中，字文白，安徽巢县人，国民党陆军二级上将。早年毕业于保定陆军军官学校，后赴黄埔军校任学生总队队长、军官团团长，为蒋介石所倚重。抗战期间任第九集团军总司令、湖南省政府主席、军事委员会政治部部长等职，参与淞沪会战，主张国共合作抗日。他一生主和，反对内战，曾三赴延安，被称为“和平将军”。1949年作为国民党政府和平谈判代表团首席代表赴北平谈判，谈判破裂后留居北平，宣布脱离国民党。中华人民共和国成立后，历任西北军政委员会副主席、全国人大常委会副委员长、国防委员会副主席等职。1969年在北京逝世。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:18:38.335370','','张家界；永州；衡阳；邵阳','永定；东安；蓝山；道县；衡东；衡南；双清；城步',null,null,null,null,'安徽巢县洪家疃','2','未发现其担任伪职的可靠记载','0',null,null,null);
