INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ecce397641e528debe52a37a738db5b1','白凤翔',null,null,'1897','1942','approx','exact','热河省围场县（今河北省围场满族蒙古族自治县）','["\\u767D\\u51E4\\u7FD4"]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u6297\\u65E5\\u5C06\\u9886","\\u9646\\u519B\\u4E2D\\u5C06"]','民国','东北军、抗日义勇军','白凤翔，热河围场人，早年投身绿林，后所部被东北军收编，历任东北军骑兵部队军官，官至骑兵军师长。1931年九一八事变后，日军侵占热河，白凤翔率部参加热河抗战与长城抗战，在塞北一带与日军作战。1936年西安事变时，白凤翔奉张学良之命率部参与临潼行动，为事变重要执行者之一。抗日战争全面爆发后，白凤翔任东北挺进军骑兵第六师师长，后升任东北挺进军副总司令，授陆军中将，转战绥远、晋北一带，坚持敌后抗战。1942年，白凤翔在绥远作战中阵亡（一说被俘后遇害），以身殉国，国民政府追念其抗战功绩。其生平由绿林而军人，由内战而抗日，最终牺牲于抗日战场，是民国时期东北军系统中具有代表性的抗日将领。','[]','2026-09-12 13:06:46.288172','2026-09-15 06:46:04.218985','','乌兰察布；包头；巴彦淖尔；石嘴山；吕梁；保定；张家口；承德；石家庄；朝阳；咸阳；宝鸡；西安；大兴安岭','丰镇；兴和；凉城；石拐；青山；乌拉特后旗；石楼；万全；围场；平山；喀喇沁左翼；凤县；高陵；呼中',null,null,null,null,'热河省围场县','3','伪东亚同盟军总司令','0',null,null,null);
