INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('ef6359e06594a594bbebe723ff7a27bd','鲍文樾',null,null,'1899','1980','approx','approx','辽宁辽阳','[]','["\\u4E1C\\u5317\\u519B\\u5C06\\u9886","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u4F2A\\u6CB3\\u5357\\u7701\\u957F","\\u6C49\\u5978"]','民国','东北军、汪伪政权','鲍文樾，辽宁辽阳人，东北军将领。早年投身奉军，曾任东北军参谋长等职，为张学良重要幕僚之一。1936年西安事变时参与其事。抗日战争爆发后，鲍文樾于1939年前后投靠日本侵略者，加入汪精卫伪政权，历任汪伪政府军政部长、参谋总长、伪河南省政府主席等要职，积极协助日军推行殖民统治、镇压抗日力量，成为臭名昭著的汉奸。抗战胜利后，鲍文樾被国民政府逮捕，以汉奸罪判处无期徒刑。中华人民共和国成立后继续关押，后获特赦。其一生由东北军将领堕落为民族罪人，是民国时期投敌卖国者的典型代表。','[]','2026-09-12 13:06:46.288172','2026-09-14 07:23:56.471226','','合肥；安庆；芜湖；聊城；南京；辽阳；南阳；黄南；新乡；沈阳','庐江；大观；芜湖经开区；镜湖；茌平；栖霞；鼓楼；镇平；河南；卫辉；原阳',null,null,null,null,'辽宁辽阳','2','伪陆军部长、伪参谋总长','0',null,null,null);
