INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('efb5f2131cc9c87878fce0e7ac07a6a0','何佩瑢',null,null,'1880','1942','approx','exact','湖北武昌','["\\u4F55\\u4F69\\u9555"]','["\\u4F2A\\u6E56\\u5317\\u7701\\u653F\\u5E9C\\u4E3B\\u5E2D","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权','何佩瑢，湖北武昌人，清末赴日本陆军士官学校留学，回国后入北洋新军，历任陆军部军械司司长、保定军校教官等职。北洋时期依附直系，曾任湖北督军署参谋长、湖北省长等职。抗日战争爆发后，武汉沦陷，何佩瑢于1938年出面组织伪武汉治安维持会，后任伪湖北省政府主席、伪国民政府委员等职，成为华中地区重要汉奸头目。他协助日军推行殖民统治，搜刮物资、镇压抗日力量，1942年病死于武汉。抗战胜利后，其汉奸罪行受到历史清算。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:41:00.937130','','恩施；黄冈；十堰；咸宁','建始；竹山',null,null,null,null,'湖北武昌','2','伪湖北省长','0',null,null,null);
