INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('f191b81a7a1b657f0650d040229b0252','汤良礼',null,null,'1901',null,'approx','unknown','广东','["T\\u0027ang Leang-li","Tang Liangli"]','["\\u6C6A\\u4F2A\\u5B98\\u5458","\\u5916\\u4EA4\\u5BA3\\u4F20\\u4EBA\\u5458","\\u62A5\\u4EBA"]','民国','汪伪政权','汤良礼，约1901年生于荷属东印度爪哇，祖籍广东，早年赴欧洲求学，通晓多国语言，曾在日内瓦国际联盟机构任职，以英文写作向西方介绍中国。1930年代回国后活跃于南京、上海报界与政界。抗日战争爆发后投靠日本，参与汪精卫伪政权的筹建与宣传工作，1939年汪精卫由河内转赴上海、南京筹组伪府期间，汤良礼为其重要幕僚之一，负责对外宣传与联络。1940年3月汪伪国民政府成立后，历任伪宣传部次长、伪外交部次长等要职，并主办英文宣传刊物，向国际社会粉饰汪伪政权、为日本侵略政策辩护，是汪伪集团对外宣传的核心人物之一。抗战胜利后，汤良礼以汉奸罪被国民政府逮捕审判，此后下落及卒年史料记载不一，一说被处决，一说瘐死狱中，亦有称其获释后流亡海外，确证不足。','[]','2026-09-12 13:06:46.288172','2026-09-14 06:41:00.440373','','桂林；九江；杭州；西安','恭城；西湖；长安',null,null,null,null,'印度尼西亚爪哇','2','汪伪政权宣传部次长','0',null,null,null);
