INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('f5ab8bc6d205df2471b4141c995a5734','陆宗舆','润生',null,'1876','1941','exact','exact','浙江海宁','["\\u9646\\u6DA6\\u751F"]','["\\u5916\\u4EA4\\u5B98","\\u5317\\u6D0B\\u653F\\u5BA2","\\u4EB2\\u65E5\\u6D3E","\\u4E94\\u56DB\\u8FD0\\u52A8\\u88AB\\u65A5\\u4E3A\\u5356\\u56FD\\u8D3C"]','民国','北洋政府（新交通系）','陆宗舆，字润生，浙江海宁人，清末举人，早年留学日本早稻田大学。回国后历任清廷巡警部主事、东三省盐务督办等职。民国成立后投靠袁世凯，任总统府财政顾问、驻日公使。1915年任驻日公使期间，与曹汝霖、章宗祥共同参与中日二十一条交涉，被舆论指为卖国。1917年任中日合办中华汇业银行总理，经手西原借款，为段祺瑞政府筹措对日借款，加深日本对华经济控制。1919年五四运动中，与曹汝霖、章宗祥同被学生斥为卖国贼，北洋政府迫于舆论将其免职。此后长期寓居天津、上海。抗日战争时期，华北沦陷后，陆宗舆于1938年出任伪中华民国临时政府行政委员会顾问、伪新民会会长等伪职，沦为汉奸。1941年病死于北平。其一生由清末外交官堕落为亲日政客，最终投敌附逆，为后世所唾弃。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:59:20.293160','','东城；北辰；和平；河北；滨海；廊坊','固安',null,null,null,null,'浙江海宁盐官','1','伪华北政务委员会顾问','0',null,null,null);
