INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('f693e1df77ec619a1676a6980d7a01ff','赵保原',null,null,'1904','1946','approx','exact','山东蓬莱','[]','["\\u4F2A\\u519B\\u5C06\\u9886","\\u56FD\\u6C11\\u515A\\u6295\\u654C\\u5C06\\u9886"]','民国','国民党军（后投汪伪）','赵保原，山东蓬莱人，早年投身军旅，隶属国民党第五十一军。抗日战争初期，曾率部在山东地区参与对日作战。1943年，时任第五十一军暂编第十二师少将师长的赵保原率部投靠汪伪政权，所部被编为伪“和平建国军”暂编第十二师，赵仍任师长，驻防山东胶东地区，配合日军对抗日根据地进行扫荡，残害抗日军民。抗日战争胜利后，赵保原部被国民党收编，继续与人民为敌。1946年，在胶东战役中，赵保原部被中国人民解放军击溃，赵保原本人被击毙，结束了其叛国投敌、与人民为敌的一生。','[]','2026-09-12 13:06:46.288172','2026-09-15 06:55:38.118803','','昆明；滁州；临沂；威海；日照；枣庄；泰安；济南；济宁；淄博；潍坊；烟台；聊城；青岛；沧州；邢台；怀化','呈贡；南谯；临沂高；兰陵；沂南；沂水；河东；威海经开区；环翠；岚山；莒县；台儿庄；山亭；滕州；宁阳；天桥；平阴；嘉祥；安丘；寒亭；昌邑；海阳；烟台经开区；牟平；芝罘；龙口；冠县；平度；胶州；青岛高…',null,null,null,null,'山东蓬莱','3','伪山东保安军头目','0',null,null,null);
INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('f698c0b4fac9c5b228086e7a96ffb0f9','苏体仁',null,null,'1888',null,'approx','unknown','山西朔县','[]','["\\u4F2A\\u5C71\\u897F\\u7701\\u957F","\\u6C6A\\u4F2A\\u5B98\\u5458","\\u6C49\\u5978"]','民国','汪伪政权/华北政务委员会','苏体仁，山西朔县人，早年留学日本，毕业于东京高等工业学校。回国后历任山西省政府委员、建设厅厅长等职。1937年抗日战争全面爆发后，太原于11月沦陷，苏体仁投降日军，出任伪山西省公署省长，成为华北地区重要的汉奸头目之一。他在任内配合日军推行治安强化运动，搜刮物资，镇压抗日力量，推行奴化教育。1943年转任汪伪政权华北政务委员会常务委员兼教育总署督办，继续为日伪效力。抗战胜利后，苏体仁被国民政府逮捕，以汉奸罪判处无期徒刑，后病死狱中。其一生由地方官员堕落为民族罪人，是民国时期汉奸群体的典型代表。','[]','2026-09-12 13:06:46.288172','2026-09-14 03:34:15.359611','','普洱；高；忻州；朔州','西',null,null,null,null,'山西朔县','1','伪华北政务委员会教育总署督办','0',null,null,null);
