INSERT INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`, `HarmLevel`, `Title`, `IsHidden`, `HiddenReason`, `HiddenAt`, `HiddenBy`) VALUES ('f8b5e65e340a4f8345c55b3aacefd7a1','卢汉','永衡',null,'1895','1974','exact','exact','云南昭通炎山','["\\u5362\\u6C38\\u8861","\\u5362\\u6C49\\uFF08\\u5B57\\u6C38\\u8861\\uFF09"]','["\\u6EC7\\u519B\\u5C06\\u9886","\\u4E91\\u5357\\u7701\\u4E3B\\u5E2D","\\u6297\\u65E5\\u5C06\\u9886","\\u8D77\\u4E49\\u5C06\\u9886"]','民国','滇军','卢汉，字永衡，云南昭通炎山人，彝族，龙云表弟。早年入云南陆军讲武堂，毕业后在滇军中历任排长、连长、营长、团长、旅长、师长等职。1927年支持龙云取得云南政权，后任云南省财政厅长、省府委员。抗日战争爆发后，任国民革命军第六十军军长，率部出滇参加台儿庄战役、武汉会战等，后任第一集团军总司令、滇南作战军总司令，驻防滇南。1945年任第一方面军总司令，赴越南接受日军投降。同年龙云被蒋介石解除云南省主席职务，卢汉继任云南省主席。1949年12月9日率部在昆明起义，宣布云南和平解放。中华人民共和国成立后，历任云南省军政委员会主席、西南行政委员会副主席、国家体委副主任、全国政协常委、民革中央常委等职。1974年5月13日在北京病逝。','[]','2026-09-12 13:06:46.288172','2026-09-14 05:59:16.056555','','昆明；昭通','呈贡；富民；晋宁',null,null,null,null,'云南昭通炎山','2','无明确汉奸记载','0',null,null,null);
